  ('o6', 'order', 'earth', 'Ordne die Kontinente nach ihrer Fläche – der größte zuerst.', '["Afrika","Europa","Asien","Südamerika"]'::jsonb, 2, array['Geographie']::text[], 'Wikipedia: Kontinent', 'https://de.wikipedia.org/wiki/Kontinent', 'ai_checked', 'published', true, '2026-10-11T12:00:00Z', 10, null, '{"en":{"question":"Order the continents by area – the largest first.","options":["Africa","Europe","Asia","South America"]}}'::jsonb),
  ('o7', 'order', 'history', 'Bring die Epochen in die richtige Reihenfolge – die älteste zuerst.', '["Mittelalter","Antike","Neuzeit","Steinzeit"]'::jsonb, 1, array['Epochen']::text[], 'Wikipedia: Epoche (Chronologie)', 'https://de.wikipedia.org/wiki/Epoche_(Chronologie)', 'ai_checked', 'published', true, '2026-10-10T12:00:00Z', 10, null, '{"en":{"question":"Put the eras in the right order – the oldest first.","options":["Middle Ages","Antiquity","Modern era","Stone Age"]}}'::jsonb),
  ('o8', 'order', 'culture', 'Ordne die Komponisten nach ihrem Geburtsjahr – der älteste zuerst.', '["Mozart","Bach","Beethoven","Vivaldi"]'::jsonb, 3, array['Musik']::text[], 'Wikipedia: Klassische Musik', 'https://de.wikipedia.org/wiki/Klassische_Musik', 'ai_checked', 'published', true, '2026-10-09T12:00:00Z', 13, null, '{"en":{"question":"Order the composers by year of birth – the oldest first.","options":["Mozart","Bach","Beethoven","Vivaldi"]}}'::jsonb),
  ('s-e1', 'estimate', 'earth', 'Schätze: Wie viel Prozent der Erdoberfläche sind von Wasser bedeckt?', '["0","100","%","1"]'::jsonb, 1, array['Geographie']::text[], 'Wikipedia: Erde', 'https://de.wikipedia.org/wiki/Erde', 'ai_checked', 'published', true, '2026-10-08T12:00:00Z', 10, null, '{"en":{"question":"Estimate: what percentage of the Earth''s surface is covered by water?","options":["0","100","%","1"]}}'::jsonb),
  ('s-e2', 'estimate', 'science', 'Schätze: Wie heiß ist die Oberfläche der Sonne?', '["1000","20000","°C","500"]'::jsonb, 2, array['Astronomie']::text[], 'Wikipedia: Sonne', 'https://de.wikipedia.org/wiki/Sonne', 'ai_checked', 'published', true, '2026-10-07T12:00:00Z', 10, null, '{"en":{"question":"Estimate: how hot is the surface of the Sun?","options":["1000","20000","°C","500"]}}'::jsonb),
  ('s-e3', 'estimate', 'science', 'Schätze: Wie weit ist der Mond im Mittel von der Erde entfernt?', '["50000","1000000","km","10000"]'::jsonb, 2, array['Astronomie']::text[], 'Wikipedia: Mond', 'https://de.wikipedia.org/wiki/Mond', 'ai_checked', 'published', true, '2026-10-06T12:00:00Z', 10, null, '{"en":{"question":"Estimate: how far is the Moon from the Earth on average?","options":["50000","1000000","km","10000"]}}'::jsonb),
  ('s-e4', 'estimate', 'technology', 'Schätze: In welchem Jahr schlug Tim Berners-Lee das World Wide Web vor?', '["1950","2010","n. Chr.","1"]'::jsonb, 2, array['Internet']::text[], 'Wikipedia: World Wide Web', 'https://de.wikipedia.org/wiki/World_Wide_Web', 'ai_checked', 'published', true, '2026-10-05T12:00:00Z', 10, null, '{"en":{"question":"Estimate: in which year did Tim Berners-Lee propose the World Wide Web?","options":["1950","2010","AD","1"]}}'::jsonb),
  ('s-e5', 'estimate', 'culture', 'Schätze: Wie viele Mitgliedstaaten haben die Vereinten Nationen?', '["50","300","Staaten","1"]'::jsonb, 2, array['Politik']::text[], 'Wikipedia: Mitgliedstaaten der Vereinten Nationen', 'https://de.wikipedia.org/wiki/Mitgliedstaaten_der_Vereinten_Nationen', 'ai_checked', 'published', true, '2026-10-04T12:00:00Z', 13, null, '{"en":{"question":"Estimate: how many member states does the United Nations have?","options":["50","300","states","1"]}}'::jsonb),
  ('s-e6', 'estimate', 'science', 'Schätze: Zu wie viel Prozent besteht der Körper eines Erwachsenen aus Wasser?', '["0","100","%","1"]'::jsonb, 1, array['Menschlicher Körper']::text[], 'Wikipedia: Körperwasser', 'https://de.wikipedia.org/wiki/Körperwasser', 'ai_checked', 'published', true, '2026-10-03T12:00:00Z', 10, null, '{"en":{"question":"Estimate: what percentage of an adult''s body consists of water?","options":["0","100","%","1"]}}'::jsonb),
  ('s-e7', 'estimate', 'earth', 'Schätze: Wie lang ist der Äquator?', '["10000","100000","km","1000"]'::jsonb, 2, array['Geographie']::text[], 'Wikipedia: Äquator', 'https://de.wikipedia.org/wiki/Äquator', 'ai_checked', 'published', true, '2026-10-02T12:00:00Z', 10, null, '{"en":{"question":"Estimate: how long is the equator?","options":["10000","100000","km","1000"]}}'::jsonb),
  ('s-e8', 'estimate', 'math', 'Wie viele Sekunden hat eine Stunde? Stell den Wert genau ein.', '["600","10000","Sekunden","100"]'::jsonb, 1, array['Rechnen']::text[], 'Wikipedia: Sekunde', 'https://de.wikipedia.org/wiki/Sekunde', 'ai_checked', 'published', true, '2026-10-01T12:00:00Z', 10, null, '{"en":{"question":"How many seconds are there in an hour? Set the exact value.","options":["600","10000","seconds","100"]}}'::jsonb),
  ('l-b1', 'blank', 'earth', 'Die Hauptstadt von Frankreich ist ___.', '["eine Stadt","Lückentext"]'::jsonb, 1, array['Geographie']::text[], 'Wikipedia: Paris', 'https://de.wikipedia.org/wiki/Paris', 'ai_checked', 'published', true, '2026-09-30T12:00:00Z', 10, null, '{"en":{"question":"The capital of France is ___.","options":["a city","Fill the gap"]}}'::jsonb),
  ('l-b2', 'blank', 'science', 'Die chemische Formel für Wasser lautet ___.', '["Buchstaben und eine Zahl","Lückentext"]'::jsonb, 1, array['Chemie']::text[], 'Wikipedia: Wasser', 'https://de.wikipedia.org/wiki/Wasser', 'ai_checked', 'published', true, '2026-09-29T12:00:00Z', 10, null, '{"en":{"question":"The chemical formula for water is ___.","options":["letters and a number","Fill the gap"]}}'::jsonb),
  ('l-b3', 'blank', 'science', 'Die Erde dreht sich in rund ___ Stunden einmal um sich selbst.', '["eine Zahl","Lückentext"]'::jsonb, 1, array['Astronomie']::text[], 'Wikipedia: Erdrotation', 'https://de.wikipedia.org/wiki/Erdrotation', 'ai_checked', 'published', true, '2026-09-28T12:00:00Z', 10, null, '{"en":{"question":"The Earth turns once on its axis in about ___ hours.","options":["a number","Fill the gap"]}}'::jsonb),
  ('l-b4', 'blank', 'science', 'Der größte Planet unseres Sonnensystems heißt ___.', '["ein Planet","Lückentext"]'::jsonb, 1, array['Astronomie']::text[], 'Wikipedia: Jupiter (Planet)', 'https://de.wikipedia.org/wiki/Jupiter_(Planet)', 'ai_checked', 'published', true, '2026-09-27T12:00:00Z', 10, null, '{"en":{"question":"The largest planet in our solar system is called ___.","options":["a planet","Fill the gap"]}}'::jsonb),
  ('l-b5', 'blank', 'science', 'Pflanzen stellen mit Licht aus Wasser und Kohlendioxid Zucker her. Dieser Vorgang heißt ___.', '["ein Fachwort","Lückentext"]'::jsonb, 2, array['Biologie']::text[], 'Wikipedia: Photosynthese', 'https://de.wikipedia.org/wiki/Photosynthese', 'ai_checked', 'published', true, '2026-09-26T12:00:00Z', 10, null, '{"en":{"question":"Plants use light to make sugar from water and carbon dioxide. This process is called ___.","options":["a technical term","Fill the gap"]}}'::jsonb),
  ('l-b6', 'blank', 'history', 'Der erste Mensch auf dem Mond hieß Neil ___.', '["ein Nachname","Lückentext"]'::jsonb, 1, array['Raumfahrt']::text[], 'Wikipedia: Neil Armstrong', 'https://de.wikipedia.org/wiki/Neil_Armstrong', 'ai_checked', 'published', true, '2026-10-16T12:00:00Z', 10, null, '{"en":{"question":"The first person on the Moon was called Neil ___.","options":["a surname","Fill the gap"]}}'::jsonb),
  ('l-b7', 'blank', 'technology', 'Die Abkürzung „www“ steht für World Wide ___.', '["ein englisches Wort","Lückentext"]'::jsonb, 1, array['Internet']::text[], 'Wikipedia: World Wide Web', 'https://de.wikipedia.org/wiki/World_Wide_Web', 'ai_checked', 'published', true, '2026-10-15T12:00:00Z', 10, null, '{"en":{"question":"The abbreviation “www” stands for World Wide ___.","options":["an English word","Fill the gap"]}}'::jsonb),
  ('l-b8', 'blank', 'math', 'Ein Dreieck hat ___ Ecken.', '["eine Zahl","Lückentext"]'::jsonb, 1, array['Geometrie']::text[], 'Wikipedia: Dreieck', 'https://de.wikipedia.org/wiki/Dreieck', 'ai_checked', 'published', true, '2026-10-14T12:00:00Z', 10, null, '{"en":{"question":"A triangle has ___ corners.","options":["a number","Fill the gap"]}}'::jsonb)
insert into public.question_answers (question_id, correct_index, explanation, translations, answer) values
  ('s1', 2, 'Au kommt vom lateinischen „aurum“. Ag steht für Silber (argentum).', '{"en":{"explanation":"Au comes from the Latin “aurum”. Ag stands for silver (argentum)."}}'::jsonb, null),
  ('s2', 1, 'Bei rund 150 Millionen Kilometern Abstand braucht Licht etwa 8 Minuten und 20 Sekunden.', '{"en":{"explanation":"At a distance of about 150 million kilometres, light takes roughly 8 minutes and 20 seconds."}}'::jsonb, null),
  ('s3', 2, 'Stickstoff macht rund 78 % der trockenen Luft aus, Sauerstoff etwa 21 %.', '{"en":{"explanation":"Nitrogen makes up about 78% of dry air, oxygen about 21%."}}'::jsonb, null),
  ('s4', 1, 'Mitochondrien erzeugen durch Zellatmung den Großteil des Energieträgers ATP.', '{"en":{"explanation":"Mitochondria produce most of the energy carrier ATP through cellular respiration."}}'::jsonb, null),
  ('s5', 1, 'Etwa 206. Neugeborene haben deutlich mehr Knochenelemente, die später zusammenwachsen.', '{"en":{"explanation":"About 206. Newborns have considerably more bone elements, which later fuse."}}'::jsonb, null),
  ('s6', 2, 'Elektronen sind negativ geladen, Protonen positiv, Neutronen neutral.', '{"en":{"explanation":"Electrons are negatively charged, protons positively, neutrons are neutral."}}'::jsonb, null),
  ('s7', 1, 'Nach einer Halbwertszeit ist die Hälfte der ursprünglichen Kerne zerfallen, nach zwei noch ein Viertel übrig.', '{"en":{"explanation":"After one half-life, half of the original nuclei have decayed; after two, a quarter remains."}}'::jsonb, null),
  ('s8', 1, 'Saturn führt deutlich: 2025 wurden 128 weitere Monde bestätigt, damit sind es 274.', '{"en":{"explanation":"Saturn leads clearly: 128 more moons were confirmed in 2025, bringing the total to 274."}}'::jsonb, null),
  ('t1', 0, 'Die CPU – der Hauptprozessor – führt die Befehle eines Programms aus.', '{"en":{"explanation":"The CPU – the main processor – executes a program''s instructions."}}'::jsonb, null),
  ('t2', 1, 'Tim Berners-Lee entwickelte das WWW ab 1989 am CERN.', '{"en":{"explanation":"Tim Berners-Lee developed the WWW at CERN from 1989."}}'::jsonb, null),
  ('t3', 1, 'Ein Byte besteht aus 8 Bit und kann 256 verschiedene Werte darstellen.', '{"en":{"explanation":"A byte consists of 8 bits and can represent 256 different values."}}'::jsonb, null),
  ('t4', 2, 'Brendan Eich entwarf die erste Version von JavaScript bei Netscape in rund zehn Tagen.', '{"en":{"explanation":"Brendan Eich designed the first version of JavaScript at Netscape in about ten days."}}'::jsonb, null),
  ('t5', 1, 'Ein generatives Modell, das vorab auf großen Textmengen trainiert wurde und auf der Transformer-Architektur beruht.', '{"en":{"explanation":"A generative model that was pre-trained on large amounts of text and is based on the transformer architecture."}}'::jsonb, null),
  ('t6', 1, 'Das Paper von Vaswani und Kollegen ersetzte rekurrente Netze durch Aufmerksamkeitsmechanismen – die Grundlage heutiger Sprachmodelle.', '{"en":{"explanation":"The paper by Vaswani and colleagues replaced recurrent networks with attention mechanisms – the basis of today''s language models."}}'::jsonb, null),
  ('t7', 1, 'Modelle zerlegen Text in Tokens und sagen Schritt für Schritt das nächste Token vorher.', '{"en":{"explanation":"Models split text into tokens and predict the next token step by step."}}'::jsonb, null),
  ('t8', 1, 'Gordon Moore beobachtete 1965, dass sich die Transistordichte regelmäßig verdoppelt – später meist mit etwa zwei Jahren angegeben.', '{"en":{"explanation":"In 1965 Gordon Moore observed that transistor density doubles regularly – later usually stated as about every two years."}}'::jsonb, null),
  ('t9', 0, 'Beim Turing-Test soll ein Mensch im Gespräch nicht mehr unterscheiden können, ob er mit Mensch oder Maschine schreibt.', '{"en":{"explanation":"In the Turing test, a person in conversation should no longer be able to tell whether they are writing with a human or a machine."}}'::jsonb, null),
  ('h1', 1, 'Am 9. November 1989 wurde die Grenze geöffnet; die Wiedervereinigung folgte am 3. Oktober 1990.', '{"en":{"explanation":"The border was opened on 9 November 1989; reunification followed on 3 October 1990."}}'::jsonb, null),
  ('h2', 1, 'Augustus regierte ab 27 v. Chr. Caesar war Diktator, aber nie Kaiser.', '{"en":{"explanation":"Augustus ruled from 27 BC. Caesar was dictator but never emperor."}}'::jsonb, null),
  ('h3', 1, 'Die Magna Carta wurde 1215 von König Johann besiegelt und gilt als frühes Grundrechtsdokument.', '{"en":{"explanation":"Magna Carta was sealed by King John in 1215 and is regarded as an early charter of rights."}}'::jsonb, null),
  ('h4', 2, 'Konstantinopel, das heutige Istanbul, blieb bis zur osmanischen Eroberung 1453 Hauptstadt.', '{"en":{"explanation":"Constantinople, today''s Istanbul, remained the capital until the Ottoman conquest in 1453."}}'::jsonb, null),
  ('h5', 2, 'Der Sturm auf die Bastille am 14. Juli 1789 gilt als ihr symbolischer Auftakt.', '{"en":{"explanation":"The storming of the Bastille on 14 July 1789 is regarded as its symbolic start."}}'::jsonb, null),
  ('h6', 1, 'Gutenbergs Verfahren aus Mainz machte Bücher erstmals in großer Zahl verfügbar.', '{"en":{"explanation":"Gutenberg''s process from Mainz made books available in large numbers for the first time."}}'::jsonb, null),
  ('h7', 1, 'Am 28. Juni 1914 wurde der österreichisch-ungarische Thronfolger Franz Ferdinand in Sarajevo erschossen.', '{"en":{"explanation":"On 28 June 1914 the Austro-Hungarian heir to the throne, Franz Ferdinand, was shot in Sarajevo."}}'::jsonb, null),
  ('h8', 1, 'Er wurde in Münster und Osnabrück ausgehandelt und prägte das europäische Staatensystem.', '{"en":{"explanation":"It was negotiated in Münster and Osnabrück and shaped the European state system."}}'::jsonb, null),
  ('h9', 2, 'Am 20. Juli 1969 landete Apollo 11; Neil Armstrong betrat als Erster die Oberfläche.', '{"en":{"explanation":"Apollo 11 landed on 20 July 1969; Neil Armstrong was the first to step onto the surface."}}'::jsonb, null),
  ('g1', 2, 'Canberra entstand als Kompromiss zwischen den Rivalen Sydney und Melbourne.', '{"en":{"explanation":"Canberra was created as a compromise between the rivals Sydney and Melbourne."}}'::jsonb, null),
  ('g2', 2, 'Der Baikalsee in Sibirien ist rund 1640 Meter tief und enthält etwa ein Fünftel des flüssigen Süßwassers der Erdoberfläche.', '{"en":{"explanation":"Lake Baikal in Siberia is about 1,640 metres deep and holds roughly a fifth of the liquid fresh water on the Earth''s surface."}}'::jsonb, null),
  ('g3', 1, 'Afrika zählt 54 international anerkannte Staaten.', '{"en":{"explanation":"Africa has 54 internationally recognised states."}}'::jsonb, null),
  ('g4', 1, 'Blauwale werden rund 30 Meter lang und weit über 100 Tonnen schwer.', '{"en":{"explanation":"Blue whales grow to about 30 metres and weigh well over 100 tonnes."}}'::jsonb, null),
  ('g5', 2, 'Zwei Kiemenherzen und ein Hauptherz – zusammen drei.', '{"en":{"explanation":"Two gill hearts and one main heart – three in total."}}'::jsonb, null),
  ('e1', 1, 'Das BIP fasst zusammen, was in einem Zeitraum im Inland an Gütern und Dienstleistungen entsteht.', '{"en":{"explanation":"GDP sums up the goods and services produced within a country in a given period."}}'::jsonb, null),
  ('e2', 2, 'Als Buchgeld startete der Euro 1999, Münzen und Scheine kamen am 1. Januar 2002.', '{"en":{"explanation":"The euro started as book money in 1999; coins and notes followed on 1 January 2002."}}'::jsonb, null),
  ('e3', 1, 'Bei Inflation steigen die Preise auf breiter Front – die Kaufkraft des Geldes sinkt.', '{"en":{"explanation":"During inflation, prices rise across the board – the purchasing power of money falls."}}'::jsonb, null),
  ('e4', 1, 'Wer eine Aktie hält, ist Miteigentümer einer Aktiengesellschaft.', '{"en":{"explanation":"Whoever holds a share is a co-owner of a public company."}}'::jsonb, null),
  ('e5', 1, 'Weil Zinsen mitverzinst werden, wächst ein Guthaben über lange Zeit immer schneller.', '{"en":{"explanation":"Because interest earns interest, savings grow faster and faster over long periods."}}'::jsonb, null),
  ('e6', 1, 'Der EZB-Rat in Frankfurt am Main entscheidet über die Geldpolitik des Euroraums.', '{"en":{"explanation":"The ECB''s Governing Council in Frankfurt am Main decides on monetary policy for the euro area."}}'::jsonb, null),
  ('c1', 2, 'Leonardo malte sie Anfang des 16. Jahrhunderts; heute hängt sie im Louvre.', '{"en":{"explanation":"Leonardo painted it in the early 16th century; today it hangs in the Louvre."}}'::jsonb, null),
  ('c2', 1, 'Goethes „Faust“ erschien in zwei Teilen, 1808 und 1832.', '{"en":{"explanation":"Goethe''s “Faust” was published in two parts, in 1808 and 1832."}}'::jsonb, null),
  ('c3', 2, 'Neun. Die letzte enthält die „Ode an die Freude“.', '{"en":{"explanation":"Nine. The last one contains the “Ode to Joy”."}}'::jsonb, null),
  ('c4', 1, 'Seit dem Austritt des Vereinigten Königreichs 2020 sind es 27.', '{"en":{"explanation":"Since the United Kingdom left in 2020 there have been 27."}}'::jsonb, null),
  ('c5', 2, 'Der Bundestag wählt auf Vorschlag des Bundespräsidenten (Artikel 63 Grundgesetz).', '{"en":{"explanation":"The Bundestag elects the chancellor on the proposal of the Federal President (Article 63 of the Basic Law)."}}'::jsonb, null),
  ('c6', 1, 'Antoni Gaudís Basilika in Barcelona ist seit 1882 im Bau.', '{"en":{"explanation":"Antoni Gaudí''s basilica in Barcelona has been under construction since 1882."}}'::jsonb, null),
  ('sm1', 1, 'Ein hartnäckiger Mythos. Bildgebende Verfahren zeigen, dass praktisch alle Hirnregionen aktiv sind – nur nicht alle gleichzeitig.', '{"en":{"explanation":"A persistent myth. Imaging shows that practically all brain regions are active – just not all at the same time."}}'::jsonb, null),
  ('sm2', 1, 'Hohe Bauwerke werden regelmäßig mehrfach getroffen – das Empire State Building etwa rund zwanzigmal pro Jahr.', '{"en":{"explanation":"Tall structures are struck repeatedly – the Empire State Building about twenty times a year."}}'::jsonb, null),
  ('tm1', 1, 'Das Internet ist das weltweite Netz aus Rechnern. Das Web ist nur ein Dienst darin – neben E-Mail und vielen anderen.', '{"en":{"explanation":"The internet is the worldwide network of computers. The web is only one service on it – alongside email and many others."}}'::jsonb, null),
  ('hm1', 1, 'Dafür ist sie viel zu schmal. Selbst aus einer niedrigen Erdumlaufbahn ist sie mit bloßem Auge kaum auszumachen.', '{"en":{"explanation":"It is far too narrow for that. Even from low Earth orbit it can hardly be made out with the naked eye."}}'::jsonb, null),
  ('gm1', 1, 'Der Everest ist der höchste Berg über dem Meeresspiegel. Weil die Erde am Äquator dicker ist, liegt aber der Gipfel des Chimborazo in Ecuador weiter vom Erdmittelpunkt entfernt.', '{"en":{"explanation":"Everest is the highest mountain above sea level. But because the Earth bulges at the equator, the summit of Chimborazo in Ecuador is farther from the centre."}}'::jsonb, null),
  ('gf1', 0, 'Botanisch ist eine Beere eine Frucht, die aus einem einzigen Fruchtknoten entsteht – wie bei der Banane. Die Erdbeere ist eine Sammelnussfrucht.', '{"en":{"explanation":"Botanically, a berry is a fruit that develops from a single ovary – like the banana. The strawberry is an aggregate fruit."}}'::jsonb, null),
  ('em1', 1, 'Im Gegenteil: Der Vorläufer „The Landlord''s Game“ von Elizabeth Magie (1904) sollte zeigen, wie Monopole auf Grundbesitz die Mehrheit verarmen lassen.', '{"en":{"explanation":"On the contrary: its forerunner, “The Landlord''s Game” by Elizabeth Magie (1904), was meant to show how land monopolies impoverish the majority."}}'::jsonb, null),
  ('ef1', 0, 'Scheine und Münzen machen nur einen kleinen Teil der Geldmenge aus. Der Rest ist Buchgeld, das Banken bei der Kreditvergabe schaffen.', '{"en":{"explanation":"Notes and coins make up only a small part of the money supply. The rest is book money that banks create when they lend."}}'::jsonb, null),
  ('cm1', 1, 'Dafür gibt es keinen archäologischen Beleg. Das Bild stammt vor allem aus dem 19. Jahrhundert – etwa von Kostümen für Wagner-Opern.', '{"en":{"explanation":"There is no archaeological evidence for this. The image comes mainly from the 19th century – for example from costumes for Wagner operas."}}'::jsonb, null),
  ('cf1', 0, 'Die Melodie der „Ode an die Freude“ aus dem letzten Satz ist seit 1985 die offizielle Hymne der Europäischen Union.', '{"en":{"explanation":"The melody of the “Ode to Joy” from the final movement has been the official anthem of the European Union since 1985."}}'::jsonb, null),
  ('sf1', 0, 'Lange hieß es, Bakterien seien zehnfach in der Überzahl. Eine Neuberechnung von 2016 kommt auf ein Verhältnis von ungefähr eins zu eins – rund 38 Billionen Bakterien auf 30 Billionen Körperzellen.', '{"en":{"explanation":"It was long said that bacteria outnumber cells ten to one. A 2016 recalculation arrives at a ratio of roughly one to one – about 38 trillion bacteria to 30 trillion body cells."}}'::jsonb, null),
  ('sf2', 0, 'Für eine Drehung um die eigene Achse braucht die Venus rund 243 Erdtage, für einen Umlauf um die Sonne nur etwa 225.', '{"en":{"explanation":"Venus needs about 243 Earth days to rotate once on its axis, but only about 225 to orbit the Sun."}}'::jsonb, null),
  ('sf3', 0, 'Kälteres Wasser ist leichter und bleibt oben, wo sich Eis bildet. Am Grund hält sich 4 °C warmes Wasser, in dem Fische überwintern.', '{"en":{"explanation":"Colder water is lighter and stays on top, where ice forms. Water at 4 °C remains at the bottom, where fish survive the winter."}}'::jsonb, null),
  ('tf1', 0, '1947 fand das Team um Grace Hopper eine Motte in einem Relais des Harvard Mark II und klebte sie ins Logbuch. Der Begriff „Bug“ für technische Fehler war allerdings schon vorher gebräuchlich.', '{"en":{"explanation":"In 1947 Grace Hopper''s team found a moth in a relay of the Harvard Mark II and taped it into the logbook. The term “bug” for technical faults was, however, already in use."}}'::jsonb, null),
  ('tf2', 0, 'Der Apollo Guidance Computer hatte 2048 Wörter beschreibbaren Speicher – ein heutiges Smartphone hat millionenfach mehr.', '{"en":{"explanation":"The Apollo Guidance Computer had 2,048 words of erasable memory – a modern smartphone has millions of times more."}}'::jsonb, null),
  ('tf3', 0, 'Sie erzeugen Text, der statistisch plausibel ist. Fehlt verlässliches Wissen, entstehen mitunter erfundene Details – sogenannte Halluzinationen. Deshalb zählen Quellen.', '{"en":{"explanation":"They generate text that is statistically plausible. Without reliable knowledge, they sometimes produce invented details – so-called hallucinations. That is why sources matter."}}'::jsonb, null),
  ('hf1', 0, 'Die Pyramide entstand um 2560 v. Chr., Kleopatra starb 30 v. Chr. – gut 2500 Jahre später. Bis zur Mondlandung 1969 waren es nur rund 2000 Jahre.', '{"en":{"explanation":"The pyramid was built around 2560 BC; Cleopatra died in 30 BC – a good 2,500 years later. Only about 2,000 years passed until the Moon landing in 1969."}}'::jsonb, null),
  ('hf2', 0, 'In Oxford wurde bereits um 1096 gelehrt. Tenochtitlan, die Hauptstadt der Azteken, wurde erst um 1325 gegründet.', '{"en":{"explanation":"Teaching took place in Oxford as early as 1096. Tenochtitlan, the Aztec capital, was not founded until about 1325."}}'::jsonb, null),
  ('hf3', 0, 'Der Britisch-Sansibarische Krieg am 27. August 1896 war nach rund 38 Minuten vorbei.', '{"en":{"explanation":"The Anglo-Zanzibar War of 27 August 1896 was over after about 38 minutes."}}'::jsonb, null),
