  ('hm3', 1, 'Mit etwa 1,68 Metern war er für seine Zeit durchschnittlich groß. Der Mythos geht auf britische Karikaturen und unterschiedliche Maßeinheiten zurück.', '{"en":{"explanation":"At about 1.68 metres he was of average height for his time. The myth goes back to British caricatures and differing units of measurement."}}'::jsonb, null),
  ('hf4', 0, 'In L’Anse aux Meadows in Neufundland wurde eine Wikingersiedlung aus der Zeit um das Jahr 1000 gefunden.', '{"en":{"explanation":"A Viking settlement from around the year 1000 was found at L''Anse aux Meadows in Newfoundland."}}'::jsonb, null),
  ('gm2', 1, 'Sie legen bei Gefahr manchmal Hals und Kopf flach auf den Boden – aus der Ferne sieht das so aus.', '{"en":{"explanation":"When threatened they sometimes lay their neck and head flat on the ground – from a distance it looks that way."}}'::jsonb, null),
  ('gf2', 0, 'Im Blitzkanal entstehen bis zu 30.000 Grad Celsius, die Sonnenoberfläche hat rund 5.500 Grad.', '{"en":{"explanation":"Temperatures in the lightning channel reach up to 30,000 degrees Celsius; the Sun''s surface is about 5,500 degrees."}}'::jsonb, null),
