  ('b12', 1, 'Starke Marken schaffen Vertrauen – und erlauben oft höhere Preise.', '{"en":{"explanation":"Strong brands create trust – and often allow higher prices."}}'::jsonb, null),
  ('b13', 0, 'Die Bauzeit eines Model T sank damit von über zwölf Stunden auf rund anderthalb.', '{"en":{"explanation":"It cut the time to build a Model T from more than twelve hours to about an hour and a half."}}'::jsonb, null),
  ('b14', 1, 'Viele Restaurant- und Hotelketten wachsen über Franchise-Partner.', '{"en":{"explanation":"Many restaurant and hotel chains grow through franchise partners."}}'::jsonb, null),
  ('b15', 2, 'Dazu gehören Produkt, Preis, Vertrieb und Werbung.', '{"en":{"explanation":"It includes product, price, distribution and advertising."}}'::jsonb, null),
  ('b16', 0, 'Die Gesellschafter haften in der Regel nur mit dem Vermögen der Gesellschaft, nicht mit ihrem privaten.', '{"en":{"explanation":"As a rule, the owners are liable only with the company''s assets, not with their private ones."}}'::jsonb, null),
  ('b17', 0, 'Mit dem Börsengang beschafft sich ein Unternehmen Geld von vielen Anlegern.', '{"en":{"explanation":"With an IPO, a company raises money from many investors."}}'::jsonb, null),
  ('bf1', 0, 'Das Unternehmen wurde 1865 in Finnland als Holzschliff- und Papierfabrik gegründet – lange vor den Mobiltelefonen.', '{"en":{"explanation":"The company was founded in Finland in 1865 as a wood pulp and paper mill – long before mobile phones."}}'::jsonb, null),
  ('bf2', 0, 'Fast hundert Jahre lang stellte Nintendo vor allem Spielkarten her, bevor Videospiele das Geschäft bestimmten.', '{"en":{"explanation":"For almost a hundred years Nintendo mainly made playing cards before video games came to dominate its business."}}'::jsonb, null),
  ('bm1', 1, 'Die große Mehrheit der Start-ups scheitert oder bleibt klein. Investoren rechnen damit, dass wenige Erfolge viele Ausfälle ausgleichen.', '{"en":{"explanation":"The great majority of start-ups fail or stay small. Investors expect a few successes to make up for many failures."}}'::jsonb, null),
  ('bm2', 1, 'Umsatz sind alle Einnahmen. Gewinn ist, was nach Abzug aller Kosten davon übrig bleibt.', '{"en":{"explanation":"Revenue is all the money coming in. Profit is what remains of it after all costs are deducted."}}'::jsonb, null),
  ('q-v-blitz', 1, 'Der Blitzkanal erhitzt die Luft so schnell, dass eine Druckwelle entsteht.', '{"en":{"explanation":"The lightning channel heats the air so quickly that a shock wave forms."}}'::jsonb, null),
  ('q-v-polarlicht', 1, 'Das Magnetfeld der Erde lenkt die Teilchen zu den Polen – deshalb sieht man Polarlichter vor allem dort.', '{"en":{"explanation":"Earth''s magnetic field guides the particles towards the poles – which is why auroras are mainly seen there."}}'::jsonb, null),
  ('q-v-keimung', 0, 'Die meisten Samen keimen auch im Dunkeln – zum Beispiel in der Erde.', '{"en":{"explanation":"Most seeds germinate even in the dark – in the soil, for example."}}'::jsonb, null),
  ('q-v-tacoma', 1, 'Der gleichmäßige Wind schaukelte die schlanke Fahrbahn immer weiter auf.', '{"en":{"explanation":"The steady wind kept amplifying the movement of the slender deck."}}'::jsonb, null),
  ('q-v-3d-druck', 2, 'Deshalb heißt das Verfahren auch additive Fertigung: Es wird Material hinzugefügt, nicht abgetragen.', '{"en":{"explanation":"That is why the process is also called additive manufacturing: material is added, not removed."}}'::jsonb, null),
  ('q-v-mars-landung', 1, 'Jezero war vor Milliarden Jahren ein See – ein guter Ort, um nach Spuren früheren Lebens zu suchen.', '{"en":{"explanation":"Billions of years ago Jezero was a lake – a good place to look for traces of past life."}}'::jsonb, null),
  ('q-v-erdaufgang', 2, 'Frank Borman, Jim Lovell und William Anders umrundeten den Mond zehnmal.', '{"en":{"explanation":"Frank Borman, Jim Lovell and William Anders circled the Moon ten times."}}'::jsonb, null),
  ('q-v-titanic', 1, 'Sie sank in der Nacht vom 14. auf den 15. April 1912 im Nordatlantik.', '{"en":{"explanation":"She sank in the North Atlantic on the night of 14 to 15 April 1912."}}'::jsonb, null),
  ('q-v-flugpioniere', 0, 'Orville Wright flog am 17. Dezember 1903 rund 37 Meter weit.', '{"en":{"explanation":"On 17 December 1903 Orville Wright flew about 37 metres."}}'::jsonb, null),
  ('q-v-buchdruck', 1, 'Aus einzelnen Lettern ließ sich jede Seite neu zusammensetzen – und danach wiederverwenden.', '{"en":{"explanation":"Any page could be composed from individual letters – and the letters reused afterwards."}}'::jsonb, null),
  ('q-v-lumiere', 1, 'Auguste und Louis Lumière führten ihren „Cinématographe“ am 28. Dezember 1895 vor.', '{"en":{"explanation":"Auguste and Louis Lumière presented their “Cinématographe” on 28 December 1895."}}'::jsonb, null),
  ('q-v-roundhay', 1, 'Louis Le Prince drehte ihn sieben Jahre vor den ersten Kinovorführungen der Brüder Lumière.', '{"en":{"explanation":"Louis Le Prince shot it seven years before the Lumière brothers'' first cinema screenings."}}'::jsonb, null),
  ('q-v-reise-zum-mond', 2, 'Méliès drehte mehr als 500 Filme und gilt als Pionier der Filmtricks.', '{"en":{"explanation":"Méliès made more than 500 films and is regarded as a pioneer of special effects."}}'::jsonb, null),
  ('q-v-orchester', 3, 'Geigen, Bratschen, Celli und Kontrabässe stellen meist mehr als die Hälfte der Musiker.', '{"en":{"explanation":"Violins, violas, cellos and double basses usually make up more than half of the players."}}'::jsonb, null),
  ('q-v-vulkan', 1, 'Tritt Magma an der Oberfläche aus, heißt es Lava.', '{"en":{"explanation":"When magma emerges at the surface, it is called lava."}}'::jsonb, null),
  ('q-v-gepard', 0, 'Wie ein Ruder gleicht der Schwanz schnelle Richtungswechsel aus.', '{"en":{"explanation":"Like a rudder, the tail compensates for rapid changes of direction."}}'::jsonb, null),
  ('q-v-oktopus', 2, 'Der kupferhaltige Blutfarbstoff Hämocyanin färbt es blau.', '{"en":{"explanation":"The copper-containing blood pigment haemocyanin makes it blue."}}'::jsonb, null),
  ('q-v-bienen', 1, 'Der Tanz verrät Richtung und Entfernung einer Futterquelle.', '{"en":{"explanation":"The dance reveals the direction and distance of a food source."}}'::jsonb, null),
  ('q-v-stare', 1, 'Im Gewimmel kann sich ein Angreifer kaum auf ein einzelnes Tier konzentrieren.', '{"en":{"explanation":"In the swirl, an attacker can hardly focus on a single animal."}}'::jsonb, null),
  ('q-v-banknoten', 2, 'Einige Länder wie Australien oder Großbritannien nutzen dagegen Kunststoff.', '{"en":{"explanation":"Some countries, such as Australia and the United Kingdom, use plastic instead."}}'::jsonb, null),
  ('q-v-muenzen', 1, 'Der Ort, an dem Münzen geprägt werden, heißt Münzprägeanstalt oder kurz Münze.', '{"en":{"explanation":"The place where coins are made is called a mint."}}'::jsonb, null),
  ('q-v-container', 0, 'Früher wurde jede Kiste und jeder Sack einzeln verladen.', '{"en":{"explanation":"In the past every crate and sack was loaded individually."}}'::jsonb, null),
  ('q-v-fliessband', 0, 'Massenproduktion senkt die Kosten pro Stück – ein Grundprinzip vieler Geschäftsmodelle.', '{"en":{"explanation":"Mass production lowers the cost per unit – a basic principle of many business models."}}'::jsonb, null),
  ('q-v-supermarkt', 1, 'Vorher reichte ein Verkäufer jede Ware über die Theke.', '{"en":{"explanation":"Before that, a shop assistant handed every item over the counter."}}'::jsonb, null),
  ('q-v-buero', 1, 'Die Anordnung QWERTY entstand in den 1870er-Jahren.', '{"en":{"explanation":"The QWERTY layout dates from the 1870s."}}'::jsonb, null),
  ('qa-herz', 2, 'Die linke Kammer hat die dickste Muskelwand, weil sie das Blut durch den ganzen Körper drücken muss. Die rechte Kammer pumpt nur zur Lunge.', '{"en":{"explanation":"The left ventricle has the thickest muscle wall because it has to push blood through the whole body. The right ventricle only pumps to the lungs."}}'::jsonb, null),
  ('qa-motor', 2, 'Nur im Arbeitstakt drückt das brennende Gas den Kolben nach unten. Die anderen drei Takte verbrauchen einen Teil dieser Energie.', '{"en":{"explanation":"Only in the power stroke does the burning gas push the piston down. The other three strokes use up part of that energy."}}'::jsonb, null),
  ('qa-gewitter', 0, 'Der schwere, negativ geladene Graupel sammelt sich unten, die leichten, positiv geladenen Eiskristalle oben. Zwischen Wolke und Boden entsteht so eine hohe Spannung.', '{"en":{"explanation":"The heavy, negatively charged graupel collects at the bottom, the light, positively charged ice crystals at the top. This creates a high voltage between cloud and ground."}}'::jsonb, null),
  ('qa-batterie', 1, 'Durch den Draht fließen Elektronen vom Minuspol zum Pluspol. Im Inneren der Batterie wandern dagegen Ionen durch den Elektrolyten.', '{"en":{"explanation":"Electrons flow through the wire from the negative to the positive terminal. Inside the battery, by contrast, ions move through the electrolyte."}}'::jsonb, null),
  ('qa-platten', 1, 'Das aufsteigende Magma erstarrt zu neuer Kruste – so wächst zum Beispiel der Atlantik jedes Jahr um einige Zentimeter.', '{"en":{"explanation":"The rising magma solidifies into new crust – this is how the Atlantic, for example, widens by a few centimetres every year."}}'::jsonb, null),
  ('m1', 3, 'Primzahlen haben genau zwei Teiler. Die kleinste ist 2 – die einzige gerade Primzahl.', '{"en":{"explanation":"Prime numbers have exactly two divisors. The smallest is 2 – the only even prime."}}'::jsonb, null),
  ('m2', 0, 'Egal wie das Dreieck aussieht: Die drei Innenwinkel ergeben zusammen immer 180 Grad.', '{"en":{"explanation":"Whatever the triangle looks like, its three interior angles always add up to 180 degrees."}}'::jsonb, null),
  ('m3', 1, 'Pi ist das Verhältnis von Umfang zu Durchmesser eines Kreises – bei jedem Kreis gleich.', '{"en":{"explanation":"Pi is the ratio of a circle''s circumference to its diameter – the same for every circle."}}'::jsonb, null),
  ('m4', 2, 'Die Quadrate über den beiden kurzen Seiten sind zusammen so groß wie das Quadrat über der längsten Seite.', '{"en":{"explanation":"The squares on the two shorter sides together equal the square on the longest side."}}'::jsonb, null),
  ('m5', 3, '10 Prozent von 200 sind 20, 5 Prozent sind 10 – zusammen 30.', '{"en":{"explanation":"10 percent of 200 is 20, 5 percent is 10 – together 30."}}'::jsonb, null),
  ('m6', 0, '12 mal 12 ergibt 144.', '{"en":{"explanation":"12 times 12 is 144."}}'::jsonb, null),
  ('m7', 1, 'Der Median teilt die sortierte Reihe in zwei Hälften. Anders als der Durchschnitt wird er von einzelnen Ausreißern kaum verzerrt.', '{"en":{"explanation":"The median splits the sorted series into two halves. Unlike the average, it is hardly distorted by single outliers."}}'::jsonb, null),
  ('m8', 2, 'Ein Hexagon ist ein Sechseck – wie die Zellen einer Bienenwabe.', '{"en":{"explanation":"A hexagon has six sides – like the cells of a honeycomb."}}'::jsonb, null),
  ('m9', 3, 'Zehnmal verdoppelt: 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024.', '{"en":{"explanation":"Doubled ten times: 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024."}}'::jsonb, null),
  ('m10', 1, 'Der Würfel hat sechs gleich wahrscheinliche Seiten, eine davon ist die Sechs.', '{"en":{"explanation":"The die has six equally likely faces, one of which is the six."}}'::jsonb, null),
  ('m11', 2, 'Jede Zahl ist die Summe der beiden vorherigen: 5 + 8 = 13.', '{"en":{"explanation":"Each number is the sum of the two before it: 5 + 8 = 13."}}'::jsonb, null),
  ('m12', 3, 'Spitze Winkel sind kleiner als 90 Grad, stumpfe größer; ein gestreckter Winkel hat 180 Grad.', '{"en":{"explanation":"Acute angles are smaller than 90 degrees, obtuse ones larger; a straight angle is 180 degrees."}}'::jsonb, null),
  ('m13', 0, 'Ein Rechteck mit 4 m Länge und 3 m Breite hat 12 Quadratmeter Fläche.', '{"en":{"explanation":"A rectangle 4 m long and 3 m wide has an area of 12 square metres."}}'::jsonb, null),
  ('m14', 1, 'I = 1, V = 5, X = 10, L = 50, C = 100, D = 500, M = 1000.', '{"en":{"explanation":"I = 1, V = 5, X = 10, L = 50, C = 100, D = 500, M = 1000."}}'::jsonb, null),
  ('m15', 2, '1.000.000 – eine Million sind tausend mal tausend.', '{"en":{"explanation":"1,000,000 – a million is a thousand times a thousand."}}'::jsonb, null),
  ('m16', 3, 'Zusammen ergeben die Zahlen 24. Geteilt durch drei Zahlen: 8.', '{"en":{"explanation":"Together the numbers add up to 24. Divided by three numbers: 8."}}'::jsonb, null),
  ('m17', 0, 'Ein Viertel ist die Hälfte von einer Hälfte: 0,5 geteilt durch 2.', '{"en":{"explanation":"A quarter is half of a half: 0.5 divided by 2."}}'::jsonb, null),
  ('m18', 1, 'Die Einteilung in 360 Grad geht auf die Babylonier zurück.', '{"en":{"explanation":"The division into 360 degrees goes back to the Babylonians."}}'::jsonb, null),
  ('m19', 3, 'Die schnell welkenden Blumen könnten alle andere Blumen sein. Über Rosen sagen die beiden Sätze dazu nichts.', '{"en":{"explanation":"The quickly wilting flowers could all be other flowers. The two statements say nothing about roses in this respect."}}'::jsonb, null),
  ('m20', 0, 'Beispiel: 3 + x = 7. Die Gleichung stimmt, wenn x den Wert 4 hat.', '{"en":{"explanation":"Example: 3 + x = 7. The equation is true when x equals 4."}}'::jsonb, null),
  ('m21', 1, 'Ein Würfel hat 8 Ecken, 12 Kanten und 6 Flächen.', '{"en":{"explanation":"A cube has 8 corners, 12 edges and 6 faces."}}'::jsonb, null),
  ('m22', 2, 'Jede Zahl ist das Doppelte der vorherigen.', '{"en":{"explanation":"Each number is double the one before."}}'::jsonb, null),
  ('m23', 3, 'x ≥ 5 heißt: x ist 5 oder eine größere Zahl.', '{"en":{"explanation":"x ≥ 5 means: x is 5 or a larger number."}}'::jsonb, null),
  ('m24', 0, '25 Prozent von 40 Euro sind 10 Euro. 40 − 10 = 30.', '{"en":{"explanation":"25 percent of 40 euros is 10 euros. 40 − 10 = 30."}}'::jsonb, null),
  ('m25', 1, 'Sein Beweis steht in den „Elementen“, einem der einflussreichsten Mathematikbücher der Geschichte.', '{"en":{"explanation":"His proof is in the “Elements”, one of the most influential mathematics books in history."}}'::jsonb, null),
  ('l1', 0, 'Adjektive beschreiben, wie etwas ist. Hier beschreibt „schnelle“ den Hund.', '{"en":{"explanation":"Adjectives describe what something is like. Here “schnelle” (fast) describes the dog."}}'::jsonb, null),
  ('l2', 1, 'Nominativ, Genitiv, Dativ und Akkusativ.', '{"en":{"explanation":"Nominative, genitive, dative and accusative."}}'::jsonb, null),
  ('l3', 2, '„Anfangen“ und „beginnen“ sind Synonyme.', '{"en":{"explanation":"“Start” and “begin” are synonyms."}}'::jsonb, null),
  ('l4', 3, '„Heiß“ und „kalt“ sind Antonyme.', '{"en":{"explanation":"“Hot” and “cold” are antonyms."}}'::jsonb, null),
  ('l5', 0, 'Beispiele sind „Anna“, „Otto“ oder „Rentner“.', '{"en":{"explanation":"Examples are “level”, “radar” or “Anna”."}}'::jsonb, null),
  ('l6', 1, 'Das Perfekt wird mit „haben“ oder „sein“ und dem Partizip gebildet. Im Gesprochenen ist es die übliche Vergangenheitsform.', '{"en":{"explanation":"The German perfect is formed with “haben” or “sein” and the participle. It is the usual past tense in spoken German."}}'::jsonb, null),
  ('l7', 2, 'Ein „falscher Freund“: Es klingt nach dem französischen „librairie“ (Buchhandlung), meint aber die Bibliothek. Buchhandlung heißt „bookshop“.', '{"en":{"explanation":"A “false friend”: it sounds like the French “librairie” (bookshop) but means “Bibliothek”. A bookshop is a “Buchhandlung”."}}'::jsonb, null),
  ('l8', 3, 'Ein typischer falscher Freund. „Bekommen“ heißt auf Englisch „to get“ oder „to receive“.', '{"en":{"explanation":"A typical false friend. The German “bekommen” means “to get” or “to receive”."}}'::jsonb, null),
  ('l9', 0, 'Es sind die 26 Buchstaben des lateinischen Alphabets. Dazu kommen ä, ö, ü und ß.', '{"en":{"explanation":"They are the 26 letters of the Latin alphabet. German adds ä, ö, ü and ß."}}'::jsonb, null),
  ('l10', 0, '„Das Herz der Stadt“ meint kein Organ, sondern das Zentrum.', '{"en":{"explanation":"“The heart of the city” does not mean an organ but the centre."}}'::jsonb, null),
  ('l11', 1, 'Friedrich Fröbel prägte den Begriff 1840. Auch „Rucksack“ und „Zeitgeist“ sind ins Englische gewandert.', '{"en":{"explanation":"Friedrich Fröbel coined the term in 1840. “Rucksack” and “zeitgeist” also made their way into English."}}'::jsonb, null),
  ('l12', 2, '„NASA“ oder „UNO“ sind Akronyme: Man spricht die Anfangsbuchstaben wie ein Wort.', '{"en":{"explanation":"“NASA” and “UNESCO” are acronyms: the initial letters are spoken as one word."}}'::jsonb, null),
  ('l13', 3, 'Auch Schwedisch, Dänisch und Norwegisch sind germanische Sprachen.', '{"en":{"explanation":"Swedish, Danish and Norwegian are Germanic languages too."}}'::jsonb, null),
  ('l14', 0, 'Sie heißen romanische Sprachen, weil sie aus dem Latein der Römer entstanden sind.', '{"en":{"explanation":"They are called Romance languages because they grew out of the Latin of the Romans."}}'::jsonb, null),
  ('l15', 1, 'Der Konjunktiv drückt aus, was nur gewünscht, gedacht oder möglich ist.', '{"en":{"explanation":"The subjunctive (Konjunktiv) expresses what is only wished for, imagined or possible."}}'::jsonb, null),
  ('l16', 0, 'Das Subjekt ist, wer oder was etwas tut. Man fragt: Wer oder was jagt?', '{"en":{"explanation":"The subject is who or what does something. Ask: who or what is chasing?"}}'::jsonb, null),
  ('l17', 3, 'Kyrillisch wird auch für Ukrainisch, Bulgarisch und Serbisch verwendet.', '{"en":{"explanation":"Cyrillic is also used for Ukrainian, Bulgarian and Serbian."}}'::jsonb, null),
  ('l18', 0, 'Die meisten davon haben nur wenige Sprecher; viele gelten als bedroht.', '{"en":{"explanation":"Most of them have only a few speakers; many are considered endangered."}}'::jsonb, null),
  ('l19', 1, '„Milch macht müde Männer munter“ ist ein bekanntes Beispiel.', '{"en":{"explanation":"“Peter Piper picked a peck of pickled peppers” is a well-known example."}}'::jsonb, null),
  ('l20', 3, 'Die Wendung stammt vermutlich aus der Sprache der Schützen: Der Nagel markierte die Mitte der Zielscheibe.', '{"en":{"explanation":"The phrase probably comes from marksmen''s language: the nail marked the centre of the target."}}'::jsonb, null),
  ('l21', 0, '„Dass“ leitet einen Nebensatz ein. Lässt sich das Wort durch „dieses“ oder „welches“ ersetzen, schreibt man „das“.', '{"en":{"explanation":"“Dass” (that) introduces a subordinate clause. If the word can be replaced by “dieses” or “welches”, it is spelled “das”."}}'::jsonb, null),
  ('l22', 1, 'Sie wird mit „to be“ und der „-ing“-Form gebildet und heißt auch „Present Continuous“.', '{"en":{"explanation":"It is formed with “to be” and the “-ing” form and is also called the present continuous."}}'::jsonb, null),
  ('s21', 3, 'Die Haut eines Erwachsenen hat eine Fläche von etwa 1,5 bis 2 Quadratmetern.', '{"en":{"explanation":"An adult''s skin has an area of about 1.5 to 2 square metres."}}'::jsonb, null),
  ('s22', 0, 'Sie enthalten den roten Farbstoff Hämoglobin, der den Sauerstoff bindet.', '{"en":{"explanation":"They contain the red pigment haemoglobin, which binds the oxygen."}}'::jsonb, null),
  ('s23', 1, 'Es sind 23 Paare – jeweils ein Chromosom von der Mutter und eines vom Vater.', '{"en":{"explanation":"There are 23 pairs – one chromosome each from the mother and the father."}}'::jsonb, null),
  ('s24', 2, 'Das Immunsystem lernt den Erreger kennen, ohne dass man die Krankheit durchmachen muss, und reagiert später schneller.', '{"en":{"explanation":"The immune system gets to know the pathogen without the person having to go through the disease, and reacts faster later on."}}'::jsonb, null),
  ('s25', 3, 'Gegen Viren – etwa bei einer Erkältung oder Grippe – helfen Antibiotika nicht.', '{"en":{"explanation":"Antibiotics do not help against viruses – for example with a cold or the flu."}}'::jsonb, null),
  ('s26', 0, 'pH 7 gilt als neutral. Werte darunter sind sauer, Werte darüber basisch.', '{"en":{"explanation":"pH 7 is considered neutral. Values below are acidic, values above are basic (alkaline)."}}'::jsonb, null),
  ('s27', 1, 'Kochsalz ist Natriumchlorid, chemische Formel NaCl.', '{"en":{"explanation":"Table salt is sodium chloride, chemical formula NaCl."}}'::jsonb, null),
  ('s28', 2, 'Trockeneis – gefrorenes Kohlendioxid – wird ohne zu schmelzen direkt zu Gas.', '{"en":{"explanation":"Dry ice – frozen carbon dioxide – turns straight into gas without melting."}}'::jsonb, null),
  ('s29', 3, 'Stößt du dich auf einem Skateboard von einer Wand ab, drückt die Wand genauso stark zurück – deshalb rollst du los.', '{"en":{"explanation":"If you push off a wall on a skateboard, the wall pushes back just as hard – that is why you roll away."}}'::jsonb, null),
  ('s30', 1, 'Ampere misst die Stromstärke, Watt die Leistung und Ohm den Widerstand.', '{"en":{"explanation":"Ampere measures current, watt measures power and ohm measures resistance."}}'::jsonb, null),
  ('s31', 1, 'Kälter geht es nicht. Auf der Kelvin-Skala ist das der Wert 0.', '{"en":{"explanation":"Nothing can be colder. On the Kelvin scale this is the value 0."}}'::jsonb, null),
  ('s32', 3, 'Im Regenbogen liegt Rot deshalb außen, Violett mit der kürzesten Wellenlänge innen.', '{"en":{"explanation":"That is why red is on the outside of a rainbow and violet, with the shortest wavelength, on the inside."}}'::jsonb, null),
  ('s33', 0, 'Die Iris ist der farbige Ring. Sie macht die Pupille in ihrer Mitte je nach Helligkeit enger oder weiter.', '{"en":{"explanation":"The iris is the coloured ring. It makes the pupil in its centre narrower or wider depending on the brightness."}}'::jsonb, null),
  ('s34', 1, 'Auf Englisch heißt er „confirmation bias“. Wer ihn kennt, sucht bewusst auch nach Gegenargumenten.', '{"en":{"explanation":"Those who know about it deliberately look for counter-arguments as well."}}'::jsonb, null),
  ('s35', 2, 'Die Hunde speichelten schließlich schon beim Ton einer Glocke. Das nennt man klassische Konditionierung.', '{"en":{"explanation":"In the end the dogs salivated at the mere sound of a bell. This is called classical conditioning."}}'::jsonb, null),
  ('s36', 3, 'In Studien dient es zum Vergleich: Nur was besser wirkt als das Placebo, gilt als wirksam.', '{"en":{"explanation":"In studies it serves as a comparison: only what works better than the placebo counts as effective."}}'::jsonb, null),
  ('s37', 0, 'Verbinden sich mehrere Atome, entsteht ein Molekül.', '{"en":{"explanation":"When several atoms bond together, a molecule is formed."}}'::jsonb, null),
  ('s38', 1, 'Es entsteht, wenn die Zellen mit Sauerstoff Energie aus der Nahrung gewinnen.', '{"en":{"explanation":"It is produced when the cells use oxygen to obtain energy from food."}}'::jsonb, null),
  ('t21', 0, 'Er leitet Datenpakete zwischen dem Heimnetz und dem Internet weiter und spannt meist auch das WLAN auf.', '{"en":{"explanation":"It forwards data packets between the home network and the internet and usually provides the Wi-Fi as well."}}'::jsonb, null),
  ('t22', 1, 'Das „s“ steht für „secure“. Ob der Inhalt der Seite stimmt, sagt es allerdings nicht.', '{"en":{"explanation":"The “s” stands for “secure”. It says nothing, however, about whether the site''s content is true."}}'::jsonb, null),
  ('t23', 2, 'Der zweite Faktor ist zum Beispiel ein Code aus einer App. Ein gestohlenes Passwort allein reicht dann nicht.', '{"en":{"explanation":"The second factor is, for example, a code from an app. A stolen password alone is then not enough."}}'::jsonb, null),
  ('t24', 3, 'Sie funktioniert wie eine Postanschrift: Datenpakete finden damit ihr Ziel.', '{"en":{"explanation":"It works like a postal address: data packets use it to find their destination."}}'::jsonb, null),
  ('t25', 0, 'Beispiele sind Windows, macOS, Linux, Android und iOS.', '{"en":{"explanation":"Examples are Windows, macOS, Linux, Android and iOS."}}'::jsonb, null),
  ('t26', 1, 'Die Vorsilben folgen dem Tausenderschritt: Kilo, Mega, Giga, Tera.', '{"en":{"explanation":"The prefixes go up in steps of a thousand: kilo, mega, giga, tera."}}'::jsonb, null),
  ('t27', 2, 'Beim Training werden die Verbindungen zwischen den Einheiten so angepasst, dass die Ergebnisse besser werden.', '{"en":{"explanation":"During training, the connections between the units are adjusted so that the results improve."}}'::jsonb, null),
  ('t28', 3, 'Sprachmodelle berechnen wahrscheinliche Wortfolgen. Deshalb sollte man wichtige Angaben immer nachprüfen.', '{"en":{"explanation":"Language models compute likely sequences of words. That is why important information should always be checked."}}'::jsonb, null),
  ('t29', 0, 'Trifft Licht auf die Zelle, setzt es im Halbleiter Elektronen in Bewegung.', '{"en":{"explanation":"When light hits the cell, it sets electrons in motion in the semiconductor."}}'::jsonb, null),
  ('t30', 2, 'Stromdurchflossene Spulen und Magnete stoßen sich ab und ziehen sich an – daraus entsteht die Drehung.', '{"en":{"explanation":"Current-carrying coils and magnets repel and attract each other – this produces the rotation."}}'::jsonb, null),
  ('t31', 3, 'Aus den Laufzeiten der Signale mehrerer Satelliten berechnet das Gerät seine Position.', '{"en":{"explanation":"The device calculates its position from the travel times of the signals of several satellites."}}'::jsonb, null),
  ('t32', 0, 'Unter dem Namen kann das Programm den Wert später wieder lesen oder ändern.', '{"en":{"explanation":"Under that name the program can read or change the value again later."}}'::jsonb, null),
  ('t33', 1, 'Deepfakes können Menschen Dinge sagen oder tun lassen, die nie passiert sind. Im Zweifel hilft der Blick auf die Quelle.', '{"en":{"explanation":"Deepfakes can make people appear to say or do things that never happened. When in doubt, check the source."}}'::jsonb, null),
  ('t34', 2, 'Je klarer die Eingabe Ziel, Kontext und gewünschtes Format beschreibt, desto brauchbarer ist meist das Ergebnis.', '{"en":{"explanation":"The more clearly the input describes the goal, context and desired format, the more useful the result usually is."}}'::jsonb, null),
  ('h21', 0, 'Angela Merkel blieb 16 Jahre im Amt, bis 2021.', '{"en":{"explanation":"Angela Merkel remained in office for 16 years, until 2021."}}'::jsonb, null),
  ('h22', 1, 'Am 3. Oktober 1990 trat die DDR der Bundesrepublik bei. Die Mauer war schon 1989 gefallen.', '{"en":{"explanation":"On 3 October 1990 East Germany joined the Federal Republic. The Wall had already fallen in 1989."}}'::jsonb, null),
  ('h23', 2, 'Im 5. Jahrhundert v. Chr. stimmten dort die Bürger selbst über Gesetze ab – Frauen, Sklaven und Zugezogene waren allerdings ausgeschlossen.', '{"en":{"explanation":"In the 5th century BC its citizens voted on laws themselves – although women, slaves and foreigners were excluded."}}'::jsonb, null),
  ('h24', 3, 'Mandela hatte zuvor 27 Jahre in Haft verbracht, weil er gegen die Rassentrennung gekämpft hatte.', '{"en":{"explanation":"Mandela had previously spent 27 years in prison for fighting against racial segregation."}}'::jsonb, null),
  ('h25', 0, 'Die Pandemie von 1346 bis 1353 wird auch „Schwarzer Tod“ genannt.', '{"en":{"explanation":"The pandemic of 1346 to 1353 is also called the “Black Death”."}}'::jsonb, null),
  ('h26', 1, 'James Watt verbesserte sie ab den 1760er-Jahren so, dass sie Fabriken, später auch Lokomotiven und Schiffe antreiben konnte.', '{"en":{"explanation":"From the 1760s James Watt improved it so that it could power factories and later locomotives and ships."}}'::jsonb, null),
  ('h27', 2, 'Washington war von 1789 bis 1797 im Amt.', '{"en":{"explanation":"Washington was in office from 1789 to 1797."}}'::jsonb, null),
  ('h28', 3, 'Die Erklärung wurde am 4. Juli 1776 angenommen – bis heute der Nationalfeiertag der USA.', '{"en":{"explanation":"The declaration was adopted on 4 July 1776 – still the national holiday of the USA."}}'::jsonb, null),
  ('h29', 0, 'Neben Seide wanderten darauf auch Gewürze, Papier, Ideen und Religionen.', '{"en":{"explanation":"Besides silk, spices, paper, ideas and religions also travelled along it."}}'::jsonb, null),
  ('h30', 2, 'Es wurde zum größten zusammenhängenden Landreich der Geschichte.', '{"en":{"explanation":"It became the largest contiguous land empire in history."}}'::jsonb, null),
  ('h31', 3, 'Der sowjetische Kosmonaut umrundete am 12. April 1961 einmal die Erde.', '{"en":{"explanation":"The Soviet cosmonaut orbited the Earth once on 12 April 1961."}}'::jsonb, null),
  ('h32', 0, 'Sie endete mit der Machtübernahme der Nationalsozialisten 1933.', '{"en":{"explanation":"It ended when the National Socialists took power in 1933."}}'::jsonb, null),
  ('h33', 1, 'Es sind bis heute die einzigen Einsätze von Atomwaffen in einem Krieg.', '{"en":{"explanation":"To this day they are the only uses of nuclear weapons in a war."}}'::jsonb, null),
  ('h34', 2, 'Er prägte die Weltpolitik von etwa 1947 bis 1989/91 – mit Wettrüsten, Stellvertreterkriegen und dem geteilten Deutschland.', '{"en":{"explanation":"It shaped world politics from about 1947 to 1989/91 – with an arms race, proxy wars and a divided Germany."}}'::jsonb, null),
  ('h35', 3, 'Fleming bemerkte, dass ein Schimmelpilz in einer Laborschale Bakterien abtötete. Daraus entstand das erste Antibiotikum.', '{"en":{"explanation":"Fleming noticed that a mould in a laboratory dish killed bacteria. This led to the first antibiotic."}}'::jsonb, null),
  ('g17', 2, 'Die Wolga ist rund 3.500 Kilometer lang und mündet ins Kaspische Meer.', '{"en":{"explanation":"The Volga is about 3,500 kilometres long and flows into the Caspian Sea."}}'::jsonb, null),
  ('g18', 3, 'Toronto ist die größte Stadt des Landes, Hauptstadt ist aber Ottawa.', '{"en":{"explanation":"Toronto is the country''s largest city, but the capital is Ottawa."}}'::jsonb, null),
  ('g19', 0, 'Nach Schätzung der Vereinten Nationen hat Indien China 2023 überholt. Beide Länder haben jeweils mehr als 1,4 Milliarden Einwohner.', '{"en":{"explanation":"According to United Nations estimates, India overtook China in 2023. Both countries have more than 1.4 billion inhabitants each."}}'::jsonb, null),
  ('g20', 2, 'Über die Straße von Gibraltar ist es mit dem Atlantik verbunden.', '{"en":{"explanation":"It is connected to the Atlantic by the Strait of Gibraltar."}}'::jsonb, null),
  ('g21', 3, 'Es entsteht vor allem beim Verbrennen von Kohle, Öl und Gas.', '{"en":{"explanation":"It is produced mainly by burning coal, oil and gas."}}'::jsonb, null),
  ('g22', 0, 'Ohne den natürlichen Treibhauseffekt wäre es auf der Erde im Mittel etwa −18 °C kalt. Zusätzliche Treibhausgase verstärken ihn.', '{"en":{"explanation":"Without the natural greenhouse effect, the Earth''s average temperature would be about −18 °C. Additional greenhouse gases strengthen it."}}'::jsonb, null),
  ('g23', 1, 'Üblicherweise betrachtet man für das Klima einen Zeitraum von 30 Jahren.', '{"en":{"explanation":"For climate, a period of 30 years is usually considered."}}'::jsonb, null),
  ('g24', 2, 'Sie liegt in etwa 15 bis 30 Kilometern Höhe in der Stratosphäre.', '{"en":{"explanation":"It lies at an altitude of about 15 to 30 kilometres in the stratosphere."}}'::jsonb, null),
  ('g25', 3, 'Vor allem der Mond zieht das Wasser der Ozeane an. An den meisten Küsten gibt es deshalb zweimal täglich Flut.', '{"en":{"explanation":"The Moon above all pulls on the water of the oceans. Most coasts therefore have high tide twice a day."}}'::jsonb, null),
  ('g26', 0, 'Dazu gehören Bären, Schweine – und der Mensch.', '{"en":{"explanation":"They include bears, pigs – and humans."}}'::jsonb, null),
  ('g27', 1, 'Flughörnchen gleiten nur. Fledertiere sind die einzigen Säugetiere, die mit Flügelschlag fliegen.', '{"en":{"explanation":"Flying squirrels only glide. Bats are the only mammals that fly by flapping their wings."}}'::jsonb, null),
  ('g28', 2, 'Der Großraum Tokio ist mit mehr als 35 Millionen Menschen der bevölkerungsreichste Ballungsraum der Welt.', '{"en":{"explanation":"With more than 35 million people, Greater Tokyo is the most populous metropolitan area in the world."}}'::jsonb, null),
  ('g29', 3, 'Die Stadt wurde im 15. Jahrhundert in rund 2.400 Metern Höhe in den Anden erbaut.', '{"en":{"explanation":"The city was built in the 15th century at an altitude of about 2,400 metres in the Andes."}}'::jsonb, null),
  ('g30', 1, 'Vielfältige Ökosysteme sind meist widerstandsfähiger gegen Störungen.', '{"en":{"explanation":"Diverse ecosystems are usually more resilient to disturbances."}}'::jsonb, null),
  ('g31', 2, 'Der Rhein entspringt in den Schweizer Alpen und mündet in den Niederlanden in die Nordsee.', '{"en":{"explanation":"The Rhine rises in the Swiss Alps and flows into the North Sea in the Netherlands."}}'::jsonb, null),
  ('e17', 0, 'Die Zinsen sind der Preis dafür, dass man das Geld jetzt schon nutzen kann.', '{"en":{"explanation":"The interest is the price for being able to use the money now."}}'::jsonb, null),
  ('e18', 1, 'Für viele Lebensmittel und Bücher gilt der ermäßigte Satz von 7 Prozent.', '{"en":{"explanation":"The reduced rate of 7 percent applies to many foods and books."}}'::jsonb, null),
  ('e19', 2, 'Vom Girokonto gehen Überweisungen, Daueraufträge und Lastschriften ab.', '{"en":{"explanation":"Transfers, standing orders and direct debits are paid from a current account."}}'::jsonb, null),
  ('e20', 0, 'Wer zwei Stunden fernsieht, „bezahlt“ mit dem, was er in dieser Zeit sonst am liebsten getan hätte.', '{"en":{"explanation":"Someone who watches TV for two hours “pays” with whatever they would most have liked to do in that time."}}'::jsonb, null),
  ('e21', 1, 'Nicht jedes Unternehmen zahlt Dividenden – manche stecken den Gewinn lieber in ihr Wachstum.', '{"en":{"explanation":"Not every company pays dividends – some prefer to put the profit into their growth."}}'::jsonb, null),
  ('e22', 2, 'Er entscheidet zum Beispiel, wie viele Dollar man für einen Euro bekommt.', '{"en":{"explanation":"It determines, for example, how many dollars you get for one euro."}}'::jsonb, null),
  ('e23', 3, 'Das klingt gut, kann aber gefährlich werden: Wer fallende Preise erwartet, verschiebt Käufe – und die Wirtschaft schrumpft.', '{"en":{"explanation":"That sounds good but can be dangerous: people who expect falling prices postpone purchases – and the economy shrinks."}}'::jsonb, null),
  ('e24', 0, 'Der Käufer erhält Zinsen und am Ende der Laufzeit sein Geld zurück – sofern der Schuldner zahlen kann.', '{"en":{"explanation":"The buyer receives interest and, at the end of the term, their money back – provided the debtor can pay."}}'::jsonb, null),
  ('e25', 1, 'Die EZB strebt eine Inflationsrate von mittelfristig zwei Prozent an.', '{"en":{"explanation":"The ECB aims for an inflation rate of two percent over the medium term."}}'::jsonb, null),
  ('e26', 2, 'Als Faustregel werden oft drei Monatsausgaben genannt, die schnell verfügbar sein sollten.', '{"en":{"explanation":"A common rule of thumb is three months'' expenses that should be quickly available."}}'::jsonb, null),
  ('b18', 2, 'Die Idee: früh lernen, was Kunden wirklich brauchen, statt lange im Verborgenen zu entwickeln.', '{"en":{"explanation":"The idea: learn early what customers really need instead of developing in secret for a long time."}}'::jsonb, null),
  ('b19', 3, 'Er beschreibt Idee, Markt, Wettbewerb und Finanzen – und ist oft Voraussetzung für Kredite oder Investoren.', '{"en":{"explanation":"It describes the idea, market, competition and finances – and is often required for loans or investors."}}'::jsonb, null),
  ('b20', 1, 'Miete und Gehälter fallen auch an, wenn nichts verkauft wird. Material dagegen zählt zu den variablen Kosten.', '{"en":{"explanation":"Rent and salaries are due even if nothing is sold. Materials, by contrast, are variable costs."}}'::jsonb, null),
  ('b21', 2, 'Wer seine Zielgruppe kennt, kann Produkt, Preis und Werbung besser auf sie abstimmen.', '{"en":{"explanation":"Those who know their target group can better tailor product, price and advertising to it."}}'::jsonb, null),
  ('b22', 3, 'Ein Unternehmen kann auf dem Papier Gewinn machen und trotzdem zahlungsunfähig werden, wenn das Geld zu spät eingeht.', '{"en":{"explanation":"A company can make a profit on paper and still become insolvent if the money comes in too late."}}'::jsonb, null),
  ('b23', 0, 'In der Regel gilt der Schutz höchstens 20 Jahre. Dafür muss die Erfindung offengelegt werden.', '{"en":{"explanation":"Protection usually lasts no more than 20 years. In return, the invention has to be disclosed."}}'::jsonb, null),
  ('c18', 3, 'Der Bundestag tagt im Reichstagsgebäude in Berlin – das Gebäude heißt so, das Parlament nicht.', '{"en":{"explanation":"The Bundestag meets in the Reichstag building in Berlin – that is the name of the building, not of the parliament."}}'::jsonb, null),
  ('c19', 0, 'Eine Wahlperiode dauert vier Jahre, sofern der Bundestag nicht vorzeitig aufgelöst wird.', '{"en":{"explanation":"A legislative period lasts four years unless the Bundestag is dissolved early."}}'::jsonb, null),
  ('c20', 2, 'Sie legt fest, wie der Staat aufgebaut ist und welche Grundrechte gelten. In Deutschland ist das das Grundgesetz.', '{"en":{"explanation":"It sets out how the state is organised and which fundamental rights apply. In Germany this is the Basic Law (Grundgesetz)."}}'::jsonb, null),
  ('c21', 3, 'In Deutschland steht sie in Artikel 5 des Grundgesetzes.', '{"en":{"explanation":"In Germany it is laid down in Article 5 of the Basic Law."}}'::jsonb, null),
  ('c22', 0, 'Viele Likes sagen nichts über den Wahrheitsgehalt. Hilfreich ist die Frage: Wer sagt das – und woher weiß er es?', '{"en":{"explanation":"Lots of likes say nothing about whether something is true. A helpful question: who says so – and how do they know?"}}'::jsonb, null),
  ('c23', 1, 'Typisch sind Formulierungen wie „Du wirst nicht glauben, was dann geschah“.', '{"en":{"explanation":"Typical phrases are things like “You won''t believe what happened next”."}}'::jsonb, null),
  ('c24', 2, 'Andere Sichtweisen tauchen dann seltener auf. Wie stark dieser Effekt wirklich ist, wird in der Forschung diskutiert.', '{"en":{"explanation":"Other points of view then appear less often. How strong this effect really is, is debated in research."}}'::jsonb, null),
  ('c25', 3, 'Das Bild entstand als Reaktion auf die Bombardierung der baskischen Stadt Gernika im Spanischen Bürgerkrieg.', '{"en":{"explanation":"The painting was a response to the bombing of the Basque town of Gernika in the Spanish Civil War."}}'::jsonb, null),
  ('c26', 0, 'Der erste Band erschien 1997. Die Reihe umfasst sieben Bände.', '{"en":{"explanation":"The first volume was published in 1997. The series comprises seven volumes."}}'::jsonb, null),
  ('c27', 1, 'Er war außerdem für seine raue Singstimme berühmt, etwa in „What a Wonderful World“.', '{"en":{"explanation":"He was also famous for his gravelly singing voice, for example in “What a Wonderful World”."}}'::jsonb, null),
  ('c28', 2, 'Der Louvre ist das meistbesuchte Kunstmuseum der Welt.', '{"en":{"explanation":"The Louvre is the most visited art museum in the world."}}'::jsonb, null),
  ('c29', 3, '„Renaissance“ bedeutet Wiedergeburt. Sie begann im 14. und 15. Jahrhundert in Italien.', '{"en":{"explanation":"“Renaissance” means rebirth. It began in Italy in the 14th and 15th centuries."}}'::jsonb, null),
  ('c30', 1, 'Die vier Violinkonzerte erschienen 1725 und gehören zu den bekanntesten Werken des Barock.', '{"en":{"explanation":"The four violin concertos were published in 1725 and are among the best-known works of the Baroque."}}'::jsonb, null),
  ('c31', 2, 'Es wird alle fünf Jahre von den Bürgerinnen und Bürgern der EU gewählt.', '{"en":{"explanation":"It is elected every five years by the citizens of the EU."}}'::jsonb, null),
  ('c32', 3, 'Die Vereinten Nationen verabschiedeten sie am 10. Dezember 1948 – heute der Tag der Menschenrechte.', '{"en":{"explanation":"The United Nations adopted it on 10 December 1948 – now Human Rights Day."}}'::jsonb, null),
  ('c33', 0, 'Monets Bild „Impression, Sonnenaufgang“ von 1872 gab der Bewegung ihren Namen.', '{"en":{"explanation":"Monet''s 1872 painting “Impression, Sunrise” gave the movement its name."}}'::jsonb, null),
  ('c34', 1, 'Hamlet, Prinz von Dänemark, grübelt in diesem Monolog über Leben und Tod.', '{"en":{"explanation":"In this soliloquy Hamlet, Prince of Denmark, broods over life and death."}}'::jsonb, null),
  ('mf1', 0, 'Es sind zwei Schreibweisen derselben Zahl. Ein Beweis: 1/3 = 0,333…, und dreimal 1/3 ist 1.', '{"en":{"explanation":"They are two ways of writing the same number. One proof: 1/3 = 0.333…, and three times 1/3 is 1."}}'::jsonb, null),
  ('mm1', 1, 'Die Münze hat kein Gedächtnis: Bei jedem Wurf stehen die Chancen wieder 50 zu 50. Der Irrtum heißt Spielerfehlschluss.', '{"en":{"explanation":"The coin has no memory: on every toss the odds are 50:50 again. The error is called the gambler''s fallacy."}}'::jsonb, null),
  ('mf2', 0, 'Die Wahrscheinlichkeit liegt knapp über 50 Prozent, weil es bei 23 Personen bereits 253 mögliche Paare gibt.', '{"en":{"explanation":"The probability is just over 50 percent, because 23 people already form 253 possible pairs."}}'::jsonb, null),
  ('mm2', 1, 'Null ist gerade: Sie lässt sich ohne Rest durch 2 teilen und liegt zwischen den ungeraden Zahlen −1 und 1.', '{"en":{"explanation":"Zero is even: it can be divided by 2 without a remainder and lies between the odd numbers −1 and 1."}}'::jsonb, null),
  ('lf1', 0, 'Das große ẞ wurde 2017 in die amtliche deutsche Rechtschreibung aufgenommen – nützlich etwa für Namen in Großbuchstaben.', '{"en":{"explanation":"The capital ẞ was added to the official German spelling rules in 2017 – useful, for example, for names written in capitals."}}'::jsonb, null),
  ('lm1', 1, 'Das ist ein beliebter Mythos. Ihre Sprachen bilden lange zusammengesetzte Wörter; die Zahl der eigentlichen Wortstämme für Schnee ist ähnlich klein wie in anderen Sprachen.', '{"en":{"explanation":"This is a popular myth. Their languages form long compound words; the number of actual word roots for snow is about as small as in other languages."}}'::jsonb, null),
  ('lf2', 0, 'Es geht auf „robota“ (Fronarbeit) zurück und wurde 1920 durch das Theaterstück „R.U.R.“ von Karel Čapek bekannt.', '{"en":{"explanation":"It goes back to “robota” (forced labour) and became known in 1920 through the play “R.U.R.” by Karel Čapek."}}'::jsonb, null),
  ('sf6', 0, 'Schimpansen und Bonobos sind unsere nächsten lebenden Verwandten. Die gemeinsamen Vorfahren lebten vor etwa sechs bis sieben Millionen Jahren.', '{"en":{"explanation":"Chimpanzees and bonobos are our closest living relatives. Our common ancestors lived about six to seven million years ago."}}'::jsonb, null),
  ('tf5', 0, 'Der Programmierer Ray Tomlinson verschickte sie im ARPANET – und führte dabei das @-Zeichen in Adressen ein.', '{"en":{"explanation":"The programmer Ray Tomlinson sent it on the ARPANET – and introduced the @ sign in addresses in the process."}}'::jsonb, null),
  ('hf5', 0, 'Das Frauenwahlrecht wurde im November 1918 eingeführt; im Januar 1919 konnten Frauen erstmals bei einer landesweiten Wahl abstimmen.', '{"en":{"explanation":"Women''s suffrage was introduced in November 1918; in January 1919 women were able to vote in a nationwide election for the first time."}}'::jsonb, null),
  ('gf3', 0, 'Als Wüste gilt ein Gebiet mit sehr wenig Niederschlag – egal ob heiß oder kalt. Die Antarktis ist größer als die Sahara, die größte heiße Wüste.', '{"en":{"explanation":"A desert is an area with very little precipitation – whether hot or cold. Antarctica is larger than the Sahara, the largest hot desert."}}'::jsonb, null),
  ('gm4', 1, 'In den Höckern steckt Fett als Energiereserve. Wasser speichern Kamele vor allem im Blut und im Gewebe.', '{"en":{"explanation":"The humps contain fat as an energy reserve. Camels store water mainly in their blood and tissue."}}'::jsonb, null),
  ('ef3', 0, 'Das Konzept wurde 2008 unter dem Pseudonym Satoshi Nakamoto veröffentlicht; im Januar 2009 entstand der erste Block.', '{"en":{"explanation":"The concept was published in 2008 under the pseudonym Satoshi Nakamoto; the first block was created in January 2009."}}'::jsonb, null),
  ('cf3', 0, 'Ein ehemaliger Mitarbeiter des Museums nahm das Bild mit. Erst mehr als zwei Jahre später tauchte es in Italien wieder auf – der Diebstahl machte es weltberühmt.', '{"en":{"explanation":"A former employee of the museum took the painting. It only resurfaced in Italy more than two years later – the theft made it world-famous."}}'::jsonb, null),
  ('cm4', 1, 'Ihn wählt die Bundesversammlung: alle Bundestagsabgeordneten und ebenso viele Vertreter der Bundesländer.', '{"en":{"explanation":"The President is elected by the Federal Convention: all members of the Bundestag and an equal number of representatives of the federal states."}}'::jsonb, null),
  ('qa-emotor', 0, 'Ohne das Umpolen würden die Kräfte die Spule nach einer halben Drehung wieder zurückziehen.', '{"en":{"explanation":"Without the reversal, the forces would pull the coil back again after half a turn."}}'::jsonb, null),
  ('qa-nn', 1, 'Jedes Gewicht wird nach jedem Fehler ein kleines Stück korrigiert – über sehr viele Beispiele hinweg.', '{"en":{"explanation":"Every weight is corrected a little after each error – over a great many examples."}}'::jsonb, null),
  ('qa-stern', 2, 'Dafür muss es im Zentrum etwa zehn Millionen Grad heiß werden.', '{"en":{"explanation":"For this, the centre has to reach about ten million degrees."}}'::jsonb, null),
  ('m26', 0, 'π · r² ist dagegen die Formel für die Fläche des Kreises.', '{"en":{"explanation":"π · r², by contrast, is the formula for the area of the circle."}}'::jsonb, null),
  ('m27', 3, 'Gerade Zahlen enden auf 0, 2, 4, 6 oder 8.', '{"en":{"explanation":"Even numbers end in 0, 2, 4, 6 or 8."}}'::jsonb, null),
  ('m28', 2, 'Eine Eselsbrücke: 5, 6, 7, 8 – „56 = 7 · 8“.', '{"en":{"explanation":"A memory aid: 5, 6, 7, 8 – “56 = 7 × 8”."}}'::jsonb, null),
  ('m29', 2, 'Beide Zahlen lassen sich durch 6 teilen, durch keine größere Zahl aber beide zugleich.', '{"en":{"explanation":"Both numbers can be divided by 6, but by no larger number at the same time."}}'::jsonb, null),
  ('m30', 2, 'Auf dem Zahlenstrahl geht man von −3 fünf Schritte nach rechts und landet bei 2.', '{"en":{"explanation":"On the number line you move five steps to the right from −3 and land on 2."}}'::jsonb, null),
  ('m31', 1, 'Punktrechnung geht vor Strichrechnung: erst 3 · 4 = 12, dann 2 + 12.', '{"en":{"explanation":"Multiplication comes before addition: first 3 × 4 = 12, then 2 + 12."}}'::jsonb, null),
  ('m32', 3, 'Länge mal Breite mal Höhe: 3 · 3 · 3 = 27.', '{"en":{"explanation":"Length times width times height: 3 × 3 × 3 = 27."}}'::jsonb, null),
  ('m33', 2, '24 Stunden mal 60 Minuten.', '{"en":{"explanation":"24 hours times 60 minutes."}}'::jsonb, null),
  ('m34', 3, 'Prozentpunkte messen den Abstand zweier Prozentwerte. Relativ gesehen ist 3 um die Hälfte größer als 2.', '{"en":{"explanation":"Percentage points measure the gap between two percentages. In relative terms, 3 is half as much again as 2."}}'::jsonb, null),
  ('m35', 1, 'Dreisatz: Ein Apfel kostet 0,50 Euro, fünf kosten das Fünffache.', '{"en":{"explanation":"Rule of three: one apple costs 0.50 euros, five cost five times as much."}}'::jsonb, null),
  ('m36', 1, '1 cm entspricht 100.000 cm – das sind 1.000 Meter.', '{"en":{"explanation":"1 cm corresponds to 100,000 cm – that is 1,000 metres."}}'::jsonb, null),
  ('m37', 2, 'Alle drei Winkel sind dann ebenfalls gleich groß: jeweils 60 Grad.', '{"en":{"explanation":"All three angles are then equal too: 60 degrees each."}}'::jsonb, null),
  ('m38', 3, 'Ein statistischer Zusammenhang (Korrelation) beweist noch keine Ursache (Kausalität). Oft steckt ein dritter Faktor dahinter.', '{"en":{"explanation":"A statistical connection (correlation) does not prove a cause (causation). Often a third factor is behind it."}}'::jsonb, null),
  ('m39', 1, 'Von rechts gelesen: 1 · 1 + 0 · 2 + 1 · 4 = 5.', '{"en":{"explanation":"Read from the right: 1 × 1 + 0 × 2 + 1 × 4 = 5."}}'::jsonb, null),
  ('m40', 1, 'Die zweite Nachkommastelle ist eine 6 – ab 5 wird aufgerundet.', '{"en":{"explanation":"The second decimal place is a 6 – from 5 upwards you round up."}}'::jsonb, null),
  ('m41', 3, 'Der Radius reicht vom Mittelpunkt zum Rand, der Durchmesser einmal quer durch den Kreis.', '{"en":{"explanation":"The radius runs from the centre to the edge, the diameter right across the circle."}}'::jsonb, null),
  ('m42', 1, 'Aus „A führt zu B“ folgt nicht „B, also A“. Vielleicht hat jemand die Straße gereinigt.', '{"en":{"explanation":"“A leads to B” does not imply “B, therefore A”. Perhaps someone has cleaned the street."}}'::jsonb, null),
  ('m43', 1, 'Verdoppelt sich die Fläche täglich, war sie am Vortag halb so groß. Exponentielles Wachstum wird lange unterschätzt.', '{"en":{"explanation":"If the area doubles daily, it was half as large the day before. Exponential growth is underestimated for a long time."}}'::jsonb, null),
  ('m44', 2, 'Vorsicht bei Übersetzungen: Das englische „billion“ ist eine Milliarde, die deutsche Billion heißt auf Englisch „trillion“.', '{"en":{"explanation":"Careful when translating: the English “billion” is a German “Milliarde”; the German “Billion” is an English “trillion”."}}'::jsonb, null),
  ('m45', 1, 'Sie verbinden die gegenüberliegenden Ecken und schneiden sich in der Mitte im rechten Winkel.', '{"en":{"explanation":"They connect opposite corners and cross in the middle at a right angle."}}'::jsonb, null),
  ('l23', 2, '„Gut“ wird unregelmäßig gesteigert – wie im Englischen „good – better – best“.', '{"en":{"explanation":"“Gut” is compared irregularly – as in English “good – better – best”."}}'::jsonb, null),
  ('l24', 3, 'Wörter mit der Verkleinerungsendung „-chen“ sind im Deutschen immer sächlich.', '{"en":{"explanation":"German words with the diminutive ending “-chen” are always neuter."}}'::jsonb, null),
  ('l25', 0, '„Laufen“, „denken“ und „regnen“ sind Verben. Man nennt sie auch Tätigkeitswörter.', '{"en":{"explanation":"“Run”, “think” and “rain” are verbs."}}'::jsonb, null),
  ('l26', 1, 'Ein unregelmäßiger Plural – wie „man – men“ oder „mouse – mice“.', '{"en":{"explanation":"An irregular plural – like “man – men” or “mouse – mice”."}}'::jsonb, null),
  ('l27', 2, '„Gone“ ist das Partizip: „I went home“, aber „I have gone home“.', '{"en":{"explanation":"“Gone” is the participle: “I went home”, but “I have gone home”."}}'::jsonb, null),
  ('l28', 3, 'Ein falscher Freund: „Aktuell“ heißt auf Englisch „current“ oder „currently“.', '{"en":{"explanation":"A false friend: the German “aktuell” means “current” or “currently”."}}'::jsonb, null),
  ('l29', 0, 'Das deutsche „Gift“ heißt auf Englisch „poison“. Beide Wörter gehen auf „geben“ zurück.', '{"en":{"explanation":"The German word “Gift” means “poison”. Both words go back to “give”."}}'::jsonb, null),
  ('l30', 2, 'Beispiele sind „bittersüß“, „alter Knabe“ oder „beredtes Schweigen“.', '{"en":{"explanation":"Examples are “bittersweet”, “deafening silence” or “living dead”."}}'::jsonb, null),
  ('l31', 3, '„Na, das hast du ja toll gemacht!“ – gesagt nach einem Missgeschick.', '{"en":{"explanation":"“Well, you did a great job there!” – said after a mishap."}}'::jsonb, null),
  ('l32', 0, 'Brasilien war eine portugiesische Kolonie – anders als die meisten Nachbarländer, in denen Spanisch gesprochen wird.', '{"en":{"explanation":"Brazil was a Portuguese colony – unlike most neighbouring countries, where Spanish is spoken."}}'::jsonb, null),
  ('l33', 2, 'Deutsch, Französisch, Italienisch und Rätoromanisch.', '{"en":{"explanation":"German, French, Italian and Romansh."}}'::jsonb, null),
  ('l34', 2, 'Bairisch, Sächsisch oder Plattdeutsch klingen sehr verschieden – und unterscheiden sich auch in Wortschatz und Grammatik.', '{"en":{"explanation":"Bavarian, Saxon or Low German sound very different – and also differ in vocabulary and grammar."}}'::jsonb, null),
  ('l35', 3, 'Auch „Büro“, „Balkon“ und „Portemonnaie“ kamen aus dem Französischen ins Deutsche.', '{"en":{"explanation":"“Bureau”, “balcony” and “ballet” also came from French."}}'::jsonb, null),
  ('l36', 0, 'Ludwik Zamenhof veröffentlichte sie 1887 als leicht erlernbare Brückensprache zwischen den Völkern.', '{"en":{"explanation":"Ludwik Zamenhof published it in 1887 as an easy-to-learn bridge language between peoples."}}'::jsonb, null),
  ('l37', 1, 'Jedes Zeichen besteht aus bis zu sechs tastbaren Punkten. Louis Braille entwickelte die Schrift um 1825.', '{"en":{"explanation":"Each character consists of up to six raised dots. Louis Braille developed the script around 1825."}}'::jsonb, null),
  ('l38', 2, 'Aus „Lager“ wird zum Beispiel „Regal“.', '{"en":{"explanation":"For example, “listen” becomes “silent”."}}'::jsonb, null),
  ('l39', 3, '„Seid“ kommt von „sein“ (ihr seid). „Seit“ ist eine Zeitangabe: seit gestern.', '{"en":{"explanation":"“Seid” comes from “sein” (to be). “Seit” refers to time: “seit gestern” (since yesterday)."}}'::jsonb, null),
  ('l40', 1, 'Sie steht für das lateinische „et cetera“ – „und die übrigen Dinge“.', '{"en":{"explanation":"It stands for the Latin “et cetera” – “and the other things”."}}'::jsonb, null),
  ('s39', 2, 'Dazu zählen vier Weisheitszähne, die oft gar nicht durchbrechen. Das Milchgebiss hat 20 Zähne.', '{"en":{"explanation":"This includes four wisdom teeth, which often never come through. The milk teeth number 20."}}'::jsonb, null),
  ('s40', 0, 'Insulin senkt den Blutzuckerspiegel. Fehlt es oder wirkt es zu schwach, entsteht Diabetes.', '{"en":{"explanation":"Insulin lowers the blood sugar level. If it is missing or too weak in effect, diabetes develops."}}'::jsonb, null),
  ('s41', 1, 'Der Steigbügel im Mittelohr ist nur etwa drei Millimeter groß und überträgt Schallschwingungen.', '{"en":{"explanation":"The stapes in the middle ear is only about three millimetres long and transmits sound vibrations."}}'::jsonb, null),
  ('s42', 1, 'Sie schwankt im Tagesverlauf leicht. Ab etwa 38 °C spricht man von Fieber.', '{"en":{"explanation":"It varies slightly over the day. From about 38 °C it is called a fever."}}'::jsonb, null),
  ('s43', 3, 'Es wird für stabile Knochen gebraucht. Im Winter reicht die Sonne in Mitteleuropa dafür oft nicht aus.', '{"en":{"explanation":"It is needed for strong bones. In winter the sun in central Europe is often not enough for this."}}'::jsonb, null),
  ('s44', 0, 'Es unterscheidet die Gruppen A, B, AB und 0. Bei einer Bluttransfusion müssen sie zusammenpassen.', '{"en":{"explanation":"It distinguishes the groups A, B, AB and O. They have to match for a blood transfusion."}}'::jsonb, null),
  ('s45', 1, 'Er ließ Lücken für noch unbekannte Elemente und sagte ihre Eigenschaften richtig voraus.', '{"en":{"explanation":"He left gaps for elements not yet known and correctly predicted their properties."}}'::jsonb, null),
  ('s46', 2, 'Edelgase wie Helium, Neon und Argon reagieren kaum mit anderen Stoffen.', '{"en":{"explanation":"Noble gases such as helium, neon and argon hardly react with other substances."}}'::jsonb, null),
  ('s47', 3, 'Sie tötet viele Keime ab. Eine Schleimschicht schützt die Magenwand vor der Säure.', '{"en":{"explanation":"It kills many germs. A layer of mucus protects the stomach wall from the acid."}}'::jsonb, null),
  ('s48', 1, 'Deshalb hört man den Donner später, als man den Blitz sieht: etwa drei Sekunden pro Kilometer Entfernung.', '{"en":{"explanation":"That is why you hear thunder later than you see lightning: about three seconds per kilometre of distance."}}'::jsonb, null),
  ('s49', 1, 'Ein Kraftwerk „erzeugt“ deshalb keine Energie – es wandelt sie nur in eine nutzbare Form um.', '{"en":{"explanation":"So a power station does not “generate” energy – it only converts it into a usable form."}}'::jsonb, null),
  ('s50', 3, 'Ein Newton ist etwa die Gewichtskraft einer Tafel Schokolade von 100 Gramm.', '{"en":{"explanation":"One newton is roughly the weight of a 100-gram bar of chocolate."}}'::jsonb, null),
  ('s51', 0, 'Es ist die Strecke, die Licht in einem Jahr zurücklegt: rund 9,5 Billionen Kilometer.', '{"en":{"explanation":"It is the distance light travels in one year: about 9.5 trillion kilometres."}}'::jsonb, null),
  ('s52', 1, 'Sie enthält mindestens 100 Milliarden Sterne.', '{"en":{"explanation":"It contains at least 100 billion stars."}}'::jsonb, null),
  ('s53', 2, 'Schwarze Löcher entstehen zum Beispiel, wenn sehr massereiche Sterne am Ende ihres Lebens in sich zusammenstürzen.', '{"en":{"explanation":"Black holes form, for example, when very massive stars collapse at the end of their lives."}}'::jsonb, null),
  ('s54', 3, 'Sein Buch heißt „Über die Entstehung der Arten“.', '{"en":{"explanation":"His book is called “On the Origin of Species”."}}'::jsonb, null),
  ('s55', 0, 'Bakterien sind eigenständige Lebewesen mit eigenem Stoffwechsel. Viren brauchen eine Wirtszelle.', '{"en":{"explanation":"Bacteria are independent living organisms with their own metabolism. Viruses need a host cell."}}'::jsonb, null),
  ('s56', 1, 'Kurzwelliges blaues Licht wird an den Luftmolekülen in alle Richtungen gestreut. Abends legt das Licht einen längeren Weg zurück – übrig bleibt Rot.', '{"en":{"explanation":"Short-wave blue light is scattered in all directions by the air molecules. In the evening the light travels a longer path – what remains is red."}}'::jsonb, null),
  ('t35', 3, 'Chrome, Firefox, Safari und Edge sind Browser. Eine Suchmaschine wie Google ist dagegen eine Website.', '{"en":{"explanation":"Chrome, Firefox, Safari and Edge are browsers. A search engine like Google, by contrast, is a website."}}'::jsonb, null),
  ('t36', 0, 'Digitale Bilder bestehen aus einem Raster vieler solcher Punkte.', '{"en":{"explanation":"Digital images consist of a grid of many such dots."}}'::jsonb, null),
  ('t37', 1, 'Beim Ausschalten wird er geleert. Dauerhaft liegen Daten auf der Festplatte oder SSD.', '{"en":{"explanation":"It is emptied when the computer is switched off. Data is stored permanently on the hard disk or SSD."}}'::jsonb, null),
  ('t38', 2, 'Geht ein Gerät kaputt oder verloren, lassen sich die Daten aus der Kopie wiederherstellen.', '{"en":{"explanation":"If a device breaks or is lost, the data can be restored from the copy."}}'::jsonb, null),
  ('t39', 3, 'Wird ein Dienst gehackt, sind bei mehrfach verwendeten Passwörtern gleich alle anderen Konten in Gefahr. Ein Passwortmanager hilft.', '{"en":{"explanation":"If a service is hacked, reused passwords put all your other accounts at risk too. A password manager helps."}}'::jsonb, null),
  ('t40', 1, 'Bei der Ende-zu-Ende-Verschlüsselung können nicht einmal die Betreiber eines Dienstes die Nachrichten mitlesen.', '{"en":{"explanation":"With end-to-end encryption, not even the operators of a service can read the messages."}}'::jsonb, null),
  ('t41', 2, 'Cookies merken sich zum Beispiel den Warenkorb oder die Anmeldung – können aber auch dazu dienen, Nutzer über Websites hinweg zu verfolgen.', '{"en":{"explanation":"Cookies remember things like the shopping basket or the login – but can also be used to track users across websites."}}'::jsonb, null),
  ('t42', 3, 'Typisch sind Kopfhörer, Lautsprecher oder Tastaturen. Benannt ist die Technik nach dem Wikingerkönig Harald Blauzahn.', '{"en":{"explanation":"Typical uses are headphones, speakers or keyboards. The technology is named after the Viking king Harald Bluetooth."}}'::jsonb, null),
  ('t43', 0, '„QR“ steht für „Quick Response“. Der Code wurde 1994 in Japan für die Autoindustrie entwickelt.', '{"en":{"explanation":"“QR” stands for “quick response”. The code was developed in Japan in 1994 for the car industry."}}'::jsonb, null),
  ('t44', 1, 'Aus den Texten lernen sie statistische Muster der Sprache – nicht, was wahr ist.', '{"en":{"explanation":"From the texts they learn statistical patterns of language – not what is true."}}'::jsonb, null),
  ('t45', 2, 'HTML legt fest, was Überschrift, Absatz, Bild oder Link ist. Das Aussehen bestimmt meist CSS.', '{"en":{"explanation":"HTML defines what is a heading, paragraph, image or link. The appearance is usually set by CSS."}}'::jsonb, null),
  ('t46', 3, 'Ruft man eine Website auf, schickt ein Server die Seite an den eigenen Browser.', '{"en":{"explanation":"When you open a website, a server sends the page to your browser."}}'::jsonb, null),
  ('t47', 0, 'Lichtimpulse laufen durch haarfeine Glasfasern – sehr schnell und über weite Strecken fast verlustfrei.', '{"en":{"explanation":"Pulses of light travel through hair-thin glass fibres – very fast and almost without loss over long distances."}}'::jsonb, null),
  ('t48', 1, 'Bekannte Lücken werden von Angreifern gezielt ausgenutzt – auf Geräten, die noch nicht aktualisiert sind.', '{"en":{"explanation":"Known holes are deliberately exploited by attackers – on devices that have not yet been updated."}}'::jsonb, null),
  ('h36', 0, 'Auch andere arbeiteten an der Idee, etwa Philipp Reis in Deutschland. Bell meldete sein Patent als Erster an.', '{"en":{"explanation":"Others were working on the idea too, such as Philipp Reis in Germany. Bell was the first to file his patent."}}'::jsonb, null),
  ('h37', 1, 'Mesopotamien bedeutet „Land zwischen den Flüssen“ und liegt im heutigen Irak. Dort entstand auch die Keilschrift.', '{"en":{"explanation":"Mesopotamia means “land between the rivers” and lies in present-day Iraq. Cuneiform writing also originated there."}}'::jsonb, null),
  ('h38', 2, 'Auf dem Stein steht derselbe Text in drei Schriften. Jean-François Champollion gelang damit 1822 der Durchbruch.', '{"en":{"explanation":"The stone bears the same text in three scripts. With it, Jean-François Champollion made the breakthrough in 1822."}}'::jsonb, null),
  ('h39', 3, 'Bis zu seinem Tod 323 v. Chr. eroberte er ein Reich, das von Griechenland bis nach Indien reichte.', '{"en":{"explanation":"By his death in 323 BC he had conquered an empire stretching from Greece to India."}}'::jsonb, null),
  ('h40', 1, 'Eine Gruppe von Senatoren erstach ihn am 15. März, weil sie eine Alleinherrschaft fürchtete.', '{"en":{"explanation":"A group of senators stabbed him on 15 March because they feared one-man rule."}}'::jsonb, null),
  ('h41', 2, 'Sein Frankenreich umfasste große Teile West- und Mitteleuropas.', '{"en":{"explanation":"His Frankish empire covered large parts of western and central Europe."}}'::jsonb, null),
  ('h42', 3, 'Magellan selbst starb unterwegs auf den Philippinen. Juan Sebastián Elcano brachte das letzte Schiff nach Hause.', '{"en":{"explanation":"Magellan himself died on the way in the Philippines. Juan Sebastián Elcano brought the last ship home."}}'::jsonb, null),
  ('h43', 0, 'Sie wurde 1431 mit etwa 19 Jahren als Ketzerin verbrannt und später heiliggesprochen.', '{"en":{"explanation":"She was burned as a heretic in 1431 at about the age of 19 and later canonised."}}'::jsonb, null),
  ('h44', 1, 'Danach wurde er auf die Atlantikinsel St. Helena verbannt.', '{"en":{"explanation":"Afterwards he was exiled to the Atlantic island of St Helena."}}'::jsonb, null),
  ('h45', 2, 'Wilhelm I. wurde im Spiegelsaal von Versailles zum Deutschen Kaiser ausgerufen.', '{"en":{"explanation":"Wilhelm I was proclaimed German Emperor in the Hall of Mirrors at Versailles."}}'::jsonb, null),
  ('h46', 2, 'Der Waffenstillstand trat am 11. November 1918 in Kraft.', '{"en":{"explanation":"The armistice came into force on 11 November 1918."}}'::jsonb, null),
  ('h47', 0, 'Fast ein Jahr lang brachten Flugzeuge der Westalliierten Lebensmittel und Kohle in die abgeriegelte Stadt.', '{"en":{"explanation":"For almost a year, aircraft of the Western Allies brought food and coal into the sealed-off city."}}'::jsonb, null),
  ('h48', 1, 'Sechs Staaten gründeten damit die Europäische Wirtschaftsgemeinschaft. Die EU in ihrer heutigen Form entstand 1993 mit dem Vertrag von Maastricht.', '{"en":{"explanation":"Six states used them to found the European Economic Community. The EU in its present form was created in 1993 by the Maastricht Treaty."}}'::jsonb, null),
  ('h49', 2, 'Ab dem 13. August 1961 riegelte die DDR die Grenze zu West-Berlin ab.', '{"en":{"explanation":"From 13 August 1961 East Germany sealed off the border to West Berlin."}}'::jsonb, null),
  ('h50', 0, 'Sie erforschte die Radioaktivität und entdeckte die Elemente Polonium und Radium.', '{"en":{"explanation":"She researched radioactivity and discovered the elements polonium and radium."}}'::jsonb, null),
  ('g32', 3, 'Australien ist größer, zählt aber als Kontinent.', '{"en":{"explanation":"Australia is larger but counts as a continent."}}'::jsonb, null),
  ('g33', 0, 'Die Stadt wurde eigens als Hauptstadt geplant und 1960 eingeweiht.', '{"en":{"explanation":"The city was planned specifically as the capital and inaugurated in 1960."}}'::jsonb, null),
  ('g34', 1, 'Istanbul ist die größte Stadt des Landes, Regierungssitz ist seit 1923 Ankara.', '{"en":{"explanation":"Istanbul is the country''s largest city; the seat of government has been Ankara since 1923."}}'::jsonb, null),
  ('g35', 2, 'Die Zugspitze in den bayerischen Alpen ist 2.962 Meter hoch.', '{"en":{"explanation":"The Zugspitze in the Bavarian Alps is 2,962 metres high."}}'::jsonb, null),
  ('g36', 3, 'Das Bergmassiv in Tansania ist 5.895 Meter hoch.', '{"en":{"explanation":"The massif in Tanzania is 5,895 metres high."}}'::jsonb, null),
  ('g37', 0, 'Der Antarktisvertrag von 1959 reserviert den Kontinent für friedliche Zwecke und die Forschung.', '{"en":{"explanation":"The Antarctic Treaty of 1959 reserves the continent for peaceful purposes and research."}}'::jsonb, null),
  ('g38', 1, 'Das Challengertief im Pazifik liegt knapp 11.000 Meter unter dem Meeresspiegel.', '{"en":{"explanation":"The Challenger Deep in the Pacific lies almost 11,000 metres below sea level."}}'::jsonb, null),
  ('g39', 2, 'Es ist das größte Korallenriff der Erde und erstreckt sich über mehr als 2.000 Kilometer.', '{"en":{"explanation":"It is the largest coral reef on Earth and stretches for more than 2,000 kilometres."}}'::jsonb, null),
  ('g40', 0, 'Delfine atmen Luft, bringen lebende Junge zur Welt und säugen sie.', '{"en":{"explanation":"Dolphins breathe air, give birth to live young and suckle them."}}'::jsonb, null),
  ('g41', 1, 'Ohne Bestäubung bilden viele Obst- und Gemüsesorten keine Früchte.', '{"en":{"explanation":"Without pollination many kinds of fruit and vegetables do not bear fruit."}}'::jsonb, null),
  ('g42', 2, 'Der innere Kern ist fest, der äußere flüssig. Seine Bewegungen erzeugen das Magnetfeld der Erde.', '{"en":{"explanation":"The inner core is solid, the outer one liquid. Its movements generate the Earth''s magnetic field."}}'::jsonb, null),
  ('g43', 3, 'Er registriert die Erschütterungen des Bodens, auch von sehr weit entfernten Beben.', '{"en":{"explanation":"It records the vibrations of the ground, even from very distant quakes."}}'::jsonb, null),
  ('g44', 0, 'Hebt oder senkt sich der Meeresboden ruckartig, setzt das die gesamte Wassersäule darüber in Bewegung.', '{"en":{"explanation":"When the sea floor rises or falls abruptly, it sets the entire column of water above it in motion."}}'::jsonb, null),
  ('g45', 1, 'Das Wasser der Erde wird dabei nicht verbraucht, sondern immer wieder neu verteilt.', '{"en":{"explanation":"The Earth''s water is not used up in the process but redistributed again and again."}}'::jsonb, null),
  ('g46', 2, 'Erdgas ist wie Kohle und Erdöl ein fossiler Brennstoff, der über Millionen Jahre entstanden ist.', '{"en":{"explanation":"Like coal and oil, natural gas is a fossil fuel that formed over millions of years."}}'::jsonb, null),
  ('g47', 3, 'Insektenfresser wie Schwalben fänden im mitteleuropäischen Winter kaum etwas zu fressen.', '{"en":{"explanation":"Insect-eaters such as swallows would find hardly anything to eat in a central European winter."}}'::jsonb, null),
  ('e27', 3, 'Nach einer sehr guten Ernte sind Erdbeeren deshalb oft günstiger.', '{"en":{"explanation":"That is why strawberries are often cheaper after a very good harvest."}}'::jsonb, null),
  ('e28', 0, 'Steigen die Preise schneller als die Löhne, sinkt die Kaufkraft.', '{"en":{"explanation":"If prices rise faster than wages, purchasing power falls."}}'::jsonb, null),
  ('e29', 1, 'Typisch ist die monatliche Miete. Bei einer Lastschrift zieht dagegen der Empfänger den Betrag ein.', '{"en":{"explanation":"The monthly rent is a typical example. With a direct debit, by contrast, the recipient collects the amount."}}'::jsonb, null),
  ('e30', 3, 'Netto ist, was tatsächlich auf dem Konto ankommt.', '{"en":{"explanation":"Net is what actually arrives in your account."}}'::jsonb, null),
  ('e31', 0, 'Dazu gehören auch die Kranken-, Pflege-, Arbeitslosen- und Unfallversicherung.', '{"en":{"explanation":"It also includes health, long-term care, unemployment and accident insurance."}}'::jsonb, null),
  ('e32', 1, 'Das Gegenteil ist der „Bullenmarkt“ mit steigenden Kursen.', '{"en":{"explanation":"The opposite is the “bull market” with rising prices."}}'::jsonb, null),
  ('e33', 2, 'Ein Smartphone wird oft in einem Land entwickelt, in einem anderen gebaut und weltweit verkauft.', '{"en":{"explanation":"A smartphone is often designed in one country, built in another and sold worldwide."}}'::jsonb, null),
  ('e34', 3, 'Zölle machen ausländische Waren teurer und schützen so heimische Hersteller – oft zulasten der Verbraucher.', '{"en":{"explanation":"Tariffs make foreign goods more expensive and thus protect domestic producers – often at the expense of consumers."}}'::jsonb, null),
  ('e35', 0, 'Sie ist für die Geldpolitik im Euroraum zuständig.', '{"en":{"explanation":"It is responsible for monetary policy in the euro area."}}'::jsonb, null),
  ('e36', 1, 'Erwerbspersonen sind alle, die arbeiten oder Arbeit suchen.', '{"en":{"explanation":"The labour force is everyone who works or is looking for work."}}'::jsonb, null),
  ('e37', 2, 'Staaten fördern damit zum Beispiel Landwirtschaft, erneuerbare Energien oder bestimmte Regionen.', '{"en":{"explanation":"States use them to support, for example, agriculture, renewable energy or particular regions."}}'::jsonb, null),
  ('e38', 3, 'Die Lücke wird meist durch neue Schulden geschlossen. Das Gegenteil ist ein Überschuss.', '{"en":{"explanation":"The gap is usually closed with new debt. The opposite is a surplus."}}'::jsonb, null),
  ('b24', 1, 'USP steht für „Unique Selling Proposition“ – das einzigartige Verkaufsversprechen.', '{"en":{"explanation":"It is the one promise that only this offering makes."}}'::jsonb, null),
  ('b25', 2, 'Auf der einen Seite steht, was das Unternehmen besitzt, auf der anderen, wie es finanziert ist. Beide Seiten sind immer gleich groß.', '{"en":{"explanation":"One side shows what the company owns, the other how it is financed. Both sides are always equal."}}'::jsonb, null),
  ('b26', 3, 'Dazu gehören Online-Shops ebenso wie Marktplätze, auf denen viele Händler verkaufen.', '{"en":{"explanation":"It includes online shops as well as marketplaces where many retailers sell."}}'::jsonb, null),
  ('b27', 0, 'Für Unternehmen bedeutet das planbare, wiederkehrende Einnahmen – etwa bei Streamingdiensten.', '{"en":{"explanation":"For companies this means predictable, recurring revenue – as with streaming services."}}'::jsonb, null),
  ('b28', 1, 'Ein Insolvenzverfahren soll klären, ob der Betrieb gerettet werden kann und wie die Gläubiger ihr Geld bekommen.', '{"en":{"explanation":"Insolvency proceedings are meant to clarify whether the business can be saved and how creditors get their money."}}'::jsonb, null),
  ('b29', 2, 'Fällt ein Zulieferer aus, kann die ganze Produktion stocken.', '{"en":{"explanation":"If one supplier fails, the whole production can come to a halt."}}'::jsonb, null),
  ('b30', 0, 'B2C steht für „Business to Consumer“ – im Gegensatz zu B2B, dem Geschäft zwischen Unternehmen.', '{"en":{"explanation":"B2C stands for “business to consumer” – as opposed to B2B, business between companies."}}'::jsonb, null),
  ('b31', 1, 'Der Vorstand führt die Geschäfte, der Aufsichtsrat kontrolliert ihn. Eigentümer sind die Inhaber der Aktien.', '{"en":{"explanation":"The executive board runs the business and the supervisory board oversees it. The owners are the holders of the shares."}}'::jsonb, null),
  ('b32', 2, 'Viele Firmen lagern etwa IT, Reinigung oder Kundendienst aus, um sich auf ihr Kerngeschäft zu konzentrieren.', '{"en":{"explanation":"Many firms outsource IT, cleaning or customer service, for example, in order to concentrate on their core business."}}'::jsonb, null),
  ('b33', 3, 'Das Wort verbindet „free“ und „premium“. Viele Apps und Spiele arbeiten so.', '{"en":{"explanation":"The word combines “free” and “premium”. Many apps and games work this way."}}'::jsonb, null),
  ('c35', 2, 'Über den Bundesrat wirken die 16 Länder an der Gesetzgebung des Bundes mit.', '{"en":{"explanation":"Through the Bundesrat the 16 states take part in federal legislation."}}'::jsonb, null),
  ('c36', 3, 'Das Europäische Parlament tagt in Straßburg und Brüssel.', '{"en":{"explanation":"The European Parliament meets in Strasbourg and Brussels."}}'::jsonb, null),
  ('c37', 0, 'Die Erzählung erschien 1915. „Kafkaesk“ nennt man bis heute beklemmend undurchschaubare Situationen.', '{"en":{"explanation":"The story was published in 1915. To this day, oppressively inscrutable situations are called “Kafkaesque”."}}'::jsonb, null),
  ('c38', 1, 'Das Buch des französischen Piloten erschien 1943 und gehört zu den meistübersetzten Büchern der Welt.', '{"en":{"explanation":"The French pilot''s book was published in 1943 and is one of the most translated books in the world."}}'::jsonb, null),
  ('c39', 2, 'Alle anderen Nobelpreise werden in Stockholm vergeben – so hat es Alfred Nobel in seinem Testament bestimmt.', '{"en":{"explanation":"All the other Nobel Prizes are awarded in Stockholm – as Alfred Nobel laid down in his will."}}'::jsonb, null),
  ('c40', 0, 'Die Academy Awards werden seit 1929 jährlich in Los Angeles vergeben.', '{"en":{"explanation":"The Academy Awards have been presented annually in Los Angeles since 1929."}}'::jsonb, null),
  ('c41', 1, 'Ihre ersten längeren Engagements hatte die Band Anfang der 1960er-Jahre in Hamburg.', '{"en":{"explanation":"The band had its first longer engagements in Hamburg in the early 1960s."}}'::jsonb, null),
  ('c42', 2, 'Rund 2,3 Milliarden Menschen gehören christlichen Kirchen an; der Islam folgt mit etwa 1,9 Milliarden.', '{"en":{"explanation":"Around 2.3 billion people belong to Christian churches; Islam follows with about 1.9 billion."}}'::jsonb, null),
  ('c43', 3, 'Gläubige Muslime verzichten in diesem Monat tagsüber auf Essen und Trinken. Er endet mit dem Fest des Fastenbrechens.', '{"en":{"explanation":"During this month, observant Muslims go without food and drink during the day. It ends with the festival of breaking the fast."}}'::jsonb, null),
  ('c44', 0, 'Traditionell hat es 5, 7 und 5 Silben und fängt einen Augenblick in der Natur ein.', '{"en":{"explanation":"Traditionally it has 5, 7 and 5 syllables and captures a moment in nature."}}'::jsonb, null),
  ('c45', 1, 'Es wurde 1919 von Walter Gropius in Weimar gegründet und 1933 unter dem Druck der Nationalsozialisten geschlossen.', '{"en":{"explanation":"It was founded in Weimar in 1919 by Walter Gropius and closed in 1933 under pressure from the National Socialists."}}'::jsonb, null),
  ('c46', 2, 'Berühmt sind vor allem ihre Selbstporträts, in denen sie Schmerz und Identität verarbeitete.', '{"en":{"explanation":"She is famous above all for her self-portraits, in which she dealt with pain and identity."}}'::jsonb, null),
  ('c47', 3, 'Er arbeitete von 1508 bis 1512 daran. Am bekanntesten ist die „Erschaffung Adams“.', '{"en":{"explanation":"He worked on it from 1508 to 1512. The best-known scene is the “Creation of Adam”."}}'::jsonb, null),
  ('c48', 0, 'Dazu gehören etwa der Kölner Dom, die Pyramiden von Gizeh und das Wattenmeer.', '{"en":{"explanation":"They include Cologne Cathedral, the Pyramids of Giza and the Wadden Sea."}}'::jsonb, null),
  ('c49', 2, 'Zehn Feldspieler und ein Torwart.', '{"en":{"explanation":"Ten outfield players and a goalkeeper."}}'::jsonb, null),
  ('c50', 3, 'Sommer- und Winterspiele wechseln sich seit 1994 im Zweijahresrhythmus ab.', '{"en":{"explanation":"Since 1994 the Summer and Winter Games have alternated every two years."}}'::jsonb, null),
  ('mf3', 0, 'Es sind etwa elfeinhalb Tage. Eine Milliarde Sekunden dagegen sind fast 32 Jahre.', '{"en":{"explanation":"It is about eleven and a half days. A billion seconds, by contrast, is almost 32 years."}}'::jsonb, null),
  ('mm3', 1, 'Das Produkt zweier negativer Zahlen ist positiv: (−2) · (−3) = 6.', '{"en":{"explanation":"The product of two negative numbers is positive: (−2) × (−3) = 6."}}'::jsonb, null),
  ('lf3', 0, 'Beide sind westgermanische Sprachen. Verwandte Wörter wie „Wasser“ und „water“ oder „Haus“ und „house“ zeigen das bis heute.', '{"en":{"explanation":"Both are West Germanic languages. Related words such as “Wasser” and “water” or “Haus” and “house” still show this today."}}'::jsonb, null),
  ('lm2', 1, 'Es gibt viele verschiedene Gebärdensprachen mit eigener Grammatik, etwa die Deutsche und die Amerikanische Gebärdensprache.', '{"en":{"explanation":"There are many different sign languages with their own grammar, such as German Sign Language and American Sign Language."}}'::jsonb, null),
  ('sf7', 0, 'Zwischen dem Aussterben dieser Dinosaurier vor rund 66 Millionen Jahren und den ersten Menschen liegen mehr als 60 Millionen Jahre.', '{"en":{"explanation":"More than 60 million years lie between the extinction of these dinosaurs about 66 million years ago and the first humans."}}'::jsonb, null),
  ('sm6', 1, 'Diese „Zungenkarte“ ist überholt. Alle Geschmacksrichtungen werden überall dort wahrgenommen, wo Geschmacksknospen sitzen.', '{"en":{"explanation":"This “tongue map” is outdated. All tastes are perceived wherever there are taste buds."}}'::jsonb, null),
  ('tm4', 1, 'WLAN ist nur die Funkverbindung zwischen Gerät und Router. Ins Internet führt erst die Leitung dahinter – WLAN kann auch ohne Internet funktionieren.', '{"en":{"explanation":"Wi-Fi is only the radio link between device and router. The line behind it leads to the internet – Wi-Fi can also work without internet."}}'::jsonb, null),
  ('hf6', 0, 'Das im Jahr 80 n. Chr. eröffnete Amphitheater war das größte der Antike.', '{"en":{"explanation":"Opened in AD 80, the amphitheatre was the largest of antiquity."}}'::jsonb, null),
  ('gf4', 0, 'Genauer gesagt sind sie Beeren. Im Alltag und in der Küche zählt man sie trotzdem zum Gemüse.', '{"en":{"explanation":"More precisely, they are berries. In everyday life and in the kitchen they still count as vegetables."}}'::jsonb, null),
  ('gf5', 0, 'Felsbilder zeigen Giraffen und Rinder. Vor etwa 5.000 Jahren wurde das Klima dort wieder trocken.', '{"en":{"explanation":"Rock paintings show giraffes and cattle. About 5,000 years ago the climate there became dry again."}}'::jsonb, null),
  ('em4', 1, 'Mehrere EU-Staaten haben eigene Währungen behalten, zum Beispiel Dänemark, Polen und Schweden.', '{"en":{"explanation":"Several EU states have kept their own currencies, for example Denmark, Poland and Sweden."}}'::jsonb, null),
  ('bf3', 0, 'Der dänische Tischler Ole Kirk Christiansen gründete die Firma 1932. Die Kunststoffsteine kamen erst später.', '{"en":{"explanation":"The Danish carpenter Ole Kirk Christiansen founded the company in 1932. The plastic bricks only came later."}}'::jsonb, null),
  ('bf4', 0, 'Das 1994 gegründete Unternehmen steckte sein Geld lange ins Wachstum. Den ersten Quartalsgewinn meldete es Ende 2001.', '{"en":{"explanation":"Founded in 1994, the company put its money into growth for a long time. It reported its first quarterly profit at the end of 2001."}}'::jsonb, null),
  ('cf4', 0, 'Trotzdem komponierte er weiter – auch seine neunte Sinfonie entstand in dieser Zeit.', '{"en":{"explanation":"He nevertheless went on composing – his Ninth Symphony was also written during this time."}}'::jsonb, null),
  ('cm5', 1, 'Er verkaufte zu Lebzeiten kaum Bilder und lebte von der Unterstützung seines Bruders. Berühmt wurde er erst nach seinem Tod 1890.', '{"en":{"explanation":"He sold hardly any paintings during his lifetime and lived on his brother''s support. He only became famous after his death in 1890."}}'::jsonb, null),
  ('qa-dna', 2, 'A paart sich mit T, G mit C. Uracil ersetzt das Thymin nur in der RNA.', '{"en":{"explanation":"A pairs with T, G with C. Uracil replaces thymine only in RNA."}}'::jsonb, null),
  ('qa-bahn', 1, 'In Sonnennähe ist die Anziehung am stärksten. Das zweite Keplersche Gesetz beschreibt, wie sich die Geschwindigkeit entlang der Bahn ändert.', '{"en":{"explanation":"Near the Sun the pull is strongest. Kepler''s second law describes how the speed changes along the orbit."}}'::jsonb, null),
  ('bq-kahneman', 0, 'System 1 arbeitet mühelos und sofort. System 2 ist das langsame, bewusste Nachdenken.', '{"en":{"explanation":"System 1 works effortlessly and instantly. System 2 is slow, deliberate thinking."}}'::jsonb, null),
  ('bq-clear', 2, 'Wer eine Gewohnheit ändern will, kann nach Clear an jedem dieser vier Schritte ansetzen.', '{"en":{"explanation":"According to Clear, anyone who wants to change a habit can start at any of these four steps."}}'::jsonb, null),
  ('bq-duhigg', 1, 'Alte Gewohnheiten lassen sich nach Duhigg kaum löschen, aber umbauen.', '{"en":{"explanation":"According to Duhigg, old habits can hardly be erased but they can be rebuilt."}}'::jsonb, null),
  ('bq-harari', 2, 'Geld, Nationen oder Unternehmen existieren, weil viele Menschen gemeinsam an sie glauben.', '{"en":{"explanation":"Money, nations or companies exist because many people jointly believe in them."}}'::jsonb, null),
  ('bq-ries', 0, 'Je schneller ein Team diese Schleife durchläuft, desto früher erfährt es, ob seine Annahmen stimmen.', '{"en":{"explanation":"The faster a team runs through this loop, the sooner it finds out whether its assumptions hold."}}'::jsonb, null),
  ('bq-thiel', 1, 'Bestehendes zu kopieren nennt Thiel „von 1 auf n“.', '{"en":{"explanation":"Thiel calls copying what already exists “from 1 to n”."}}'::jsonb, null),
  ('bq-rumelt', 2, 'Auf die Diagnose folgen eine Leitlinie und abgestimmte Maßnahmen. Ziele allein sind für Rumelt noch keine Strategie.', '{"en":{"explanation":"The diagnosis is followed by a guiding policy and coherent actions. For Rumelt, goals alone are not yet a strategy."}}'::jsonb, null),
  ('bq-christensen', 3, 'Marktführer ignorieren sie oft, weil das neue Geschäft anfangs klein und wenig profitabel ist.', '{"en":{"explanation":"Market leaders often ignore it because the new business is small and not very profitable at first."}}'::jsonb, null),
  ('bq-housel', 3, 'Der Zinseszins entfaltet seine Wirkung erst über Jahrzehnte.', '{"en":{"explanation":"Compound interest only unfolds its effect over decades."}}'::jsonb, null),
  ('bq-cialdini', 0, 'Das wirkt sogar bei Geschenken, um die wir nie gebeten haben.', '{"en":{"explanation":"This works even for gifts we never asked for."}}'::jsonb, null),
  ('bq-rosling', 1, 'Tatsächlich lebt die große Mehrheit der Menschen zwischen den Extremen.', '{"en":{"explanation":"In fact the great majority of people live between the extremes."}}'::jsonb, null),
  ('bq-meadows', 1, 'Beispiel Zinseszins: mehr Guthaben bringt mehr Zinsen, die das Guthaben weiter erhöhen. Ein Thermostat ist dagegen eine ausgleichende Rückkopplung.', '{"en":{"explanation":"Example compound interest: a bigger balance brings more interest, which increases the balance further. A thermostat, by contrast, is a balancing loop."}}'::jsonb, null),
  ('bq-newport', 2, 'Das Gegenteil nennt er „Shallow Work“: Aufgaben, die man auch halb abgelenkt erledigen kann.', '{"en":{"explanation":"He calls the opposite “shallow work”: tasks that can be done half-distracted."}}'::jsonb, null),
  ('bq-dweck', 3, 'Im statischen Selbstbild gelten Begabung und Intelligenz dagegen als feststehend.', '{"en":{"explanation":"In the fixed mindset, by contrast, talent and intelligence are seen as given."}}'::jsonb, null),
  ('bq-brown', 3, 'Jedes Abrufen aus dem Gedächtnis festigt die Erinnerung – das nennt man Testeffekt.', '{"en":{"explanation":"Every act of retrieval from memory strengthens the memory – this is called the testing effect."}}'::jsonb, null),
  ('bq-dawkins', 2, 'Gemeint waren Melodien, Ideen oder Redewendungen. Die Bedeutung „Internet-Witzbild“ kam erst Jahrzehnte später.', '{"en":{"explanation":"He meant tunes, ideas or catchphrases. The meaning “internet joke image” only came decades later."}}'::jsonb, null),
  ('bq-hawking', 2, 'Durch diese Hawking-Strahlung können Schwarze Löcher über extrem lange Zeit Masse verlieren.', '{"en":{"explanation":"Through this Hawking radiation, black holes can lose mass over extremely long periods."}}'::jsonb, null),
  ('bq-diamond', 1, 'Entscheidend waren für ihn zähmbare Pflanzen und Tiere und die Ausrichtung der Kontinente.', '{"en":{"explanation":"For him the decisive factors were domesticable plants and animals and the orientation of the continents."}}'::jsonb, null),
  ('bq-aurel', 2, 'Seine „Selbstbetrachtungen“ sind eines der bekanntesten Werke der späten Stoa.', '{"en":{"explanation":"His “Meditations” are one of the best-known works of late Stoicism."}}'::jsonb, null),
  ('bq-carnegie', 3, 'Kritik löst nach Carnegie vor allem Verteidigung aus – echtes Interesse dagegen Vertrauen.', '{"en":{"explanation":"According to Carnegie, criticism mainly triggers defensiveness – genuine interest, by contrast, trust."}}'::jsonb, null),
  ('o1', 0, 'Buchdruck (um 1450), Französische Revolution (1789), Mondlandung (1969), Fall der Berliner Mauer (1989).', '{"en":{"explanation":"Printing (around 1450), French Revolution (1789), Moon landing (1969), fall of the Berlin Wall (1989)."}}'::jsonb, '{"order":[3,1,0,2]}'::jsonb),
  ('o2', 0, 'Merkur, Venus, Erde, Mars – das sind die vier Gesteinsplaneten des inneren Sonnensystems.', '{"en":{"explanation":"Mercury, Venus, Earth, Mars – these are the four rocky planets of the inner solar system."}}'::jsonb, '{"order":[1,3,2,0]}'::jsonb),
  ('o3', 0, 'Telefon (1876), Transistor (1947), World Wide Web (1989), iPhone (2007).', '{"en":{"explanation":"Telephone (1876), transistor (1947), World Wide Web (1989), iPhone (2007)."}}'::jsonb, '{"order":[1,3,0,2]}'::jsonb),
  ('o4', 0, 'Ansaugen, Verdichten, Arbeiten, Ausstoßen – nur der dritte Takt liefert Kraft.', '{"en":{"explanation":"Intake, compression, power, exhaust – only the third stroke delivers power."}}'::jsonb, '{"order":[2,0,3,1]}'::jsonb),
  ('o5', 0, '1/4 = 0,25 · 0,3 · 0,5 · 2/3 ≈ 0,67.', '{"en":{"explanation":"1/4 = 0.25 · 0.3 · 0.5 · 2/3 ≈ 0.67."}}'::jsonb, '{"order":[1,2,0,3]}'::jsonb),
  ('o6', 0, 'Asien (rund 44 Mio. km²), Afrika (30 Mio.), Südamerika (18 Mio.), Europa (10 Mio.).', '{"en":{"explanation":"Asia (about 44 million km²), Africa (30 million), South America (18 million), Europe (10 million)."}}'::jsonb, '{"order":[2,0,3,1]}'::jsonb),
  ('o7', 0, 'Steinzeit, Antike, Mittelalter, Neuzeit.', '{"en":{"explanation":"Stone Age, antiquity, Middle Ages, modern era."}}'::jsonb, '{"order":[3,1,0,2]}'::jsonb),
  ('o8', 0, 'Vivaldi (1678), Bach (1685), Mozart (1756), Beethoven (1770).', '{"en":{"explanation":"Vivaldi (1678), Bach (1685), Mozart (1756), Beethoven (1770)."}}'::jsonb, '{"order":[3,1,0,2]}'::jsonb),
  ('s-e1', 0, 'Es sind rund 71 Prozent. Der größte Teil davon ist Salzwasser in den Ozeanen.', '{"en":{"explanation":"It is about 71 percent. Most of it is salt water in the oceans."}}'::jsonb, '{"value":71,"abs":5}'::jsonb),
  ('s-e2', 0, 'Rund 5.500 °C. Im Kern der Sonne sind es dagegen etwa 15 Millionen Grad.', '{"en":{"explanation":"About 5,500 °C. In the Sun''s core, by contrast, it is around 15 million degrees."}}'::jsonb, '{"value":5500,"abs":1000}'::jsonb),
  ('s-e3', 0, 'Im Mittel rund 384.400 Kilometer. Licht braucht für die Strecke gut eine Sekunde.', '{"en":{"explanation":"About 384,400 kilometres on average. Light needs just over a second for the distance."}}'::jsonb, '{"value":384400,"abs":60000}'::jsonb),
  ('s-e4', 0, '1989 am Forschungszentrum CERN. Die erste Website ging 1991 online.', '{"en":{"explanation":"In 1989 at the CERN research centre. The first website went online in 1991."}}'::jsonb, '{"value":1989,"abs":3}'::jsonb),
  ('s-e5', 0, '193 Staaten. Als bisher letzter kam 2011 der Südsudan dazu.', '{"en":{"explanation":"193 states. The most recent to join was South Sudan in 2011."}}'::jsonb, '{"value":193,"abs":10}'::jsonb),
  ('s-e6', 0, 'Etwa 60 Prozent – bei Säuglingen ist der Anteil höher, im Alter sinkt er.', '{"en":{"explanation":"About 60 percent – the share is higher in infants and falls in old age."}}'::jsonb, '{"value":60,"abs":8}'::jsonb),
  ('s-e7', 0, 'Rund 40.075 Kilometer. Das Meter wurde ursprünglich so festgelegt, dass der Erdumfang über die Pole 40.000 Kilometer beträgt.', '{"en":{"explanation":"About 40,075 kilometres. The metre was originally defined so that the Earth''s circumference through the poles is 40,000 kilometres."}}'::jsonb, '{"value":40075,"abs":5000}'::jsonb),
  ('s-e8', 0, '60 Minuten mal 60 Sekunden: 3.600.', '{"en":{"explanation":"60 minutes times 60 seconds: 3,600."}}'::jsonb, '{"value":3600,"abs":0}'::jsonb),
  ('l-b1', 0, 'Paris ist die Hauptstadt und mit Abstand größte Stadt Frankreichs.', '{"en":{"explanation":"Paris is the capital and by far the largest city in France."}}'::jsonb, '{"accept":["paris"],"show":"Paris"}'::jsonb),
  ('l-b2', 0, 'H₂O: zwei Wasserstoffatome und ein Sauerstoffatom.', '{"en":{"explanation":"H₂O: two hydrogen atoms and one oxygen atom."}}'::jsonb, '{"accept":["h2o","h₂o","h 2 o"],"show":"H₂O"}'::jsonb),
  ('l-b3', 0, 'In rund 24 Stunden – deshalb gibt es Tag und Nacht.', '{"en":{"explanation":"In about 24 hours – which is why there is day and night."}}'::jsonb, '{"accept":["24","vierundzwanzig","twenty-four","twenty four"],"show":"24"}'::jsonb),
  ('l-b4', 0, 'Jupiter: In ihm hätte die Erde mehr als tausendmal Platz.', '{"en":{"explanation":"Jupiter: the Earth would fit into it more than a thousand times."}}'::jsonb, '{"accept":["jupiter"],"show":"Jupiter"}'::jsonb),
  ('l-b5', 0, 'Fotosynthese. Dabei wird auch der Sauerstoff frei, den wir atmen.', '{"en":{"explanation":"Photosynthesis. It also releases the oxygen we breathe."}}'::jsonb, '{"accept":["fotosynthese","photosynthese","photosynthesis"],"show":"Fotosynthese"}'::jsonb),
  ('l-b6', 0, 'Neil Armstrong betrat den Mond am 21. Juli 1969 (mitteleuropäischer Zeit).', '{"en":{"explanation":"Neil Armstrong stepped onto the Moon on 21 July 1969 (Central European Time)."}}'::jsonb, '{"accept":["armstrong"],"show":"Armstrong"}'::jsonb),
  ('l-b7', 0, 'World Wide Web – das „weltweite Netz“ aus verlinkten Seiten.', '{"en":{"explanation":"World Wide Web – the worldwide network of linked pages."}}'::jsonb, '{"accept":["web"],"show":"Web"}'::jsonb),
  ('l-b8', 0, 'Drei Ecken, drei Seiten – und die Innenwinkel ergeben zusammen 180 Grad.', '{"en":{"explanation":"Three corners, three sides – and the interior angles add up to 180 degrees."}}'::jsonb, '{"accept":["3","drei","three"],"show":"3"}'::jsonb)
insert into public.videos (id, category_id, title, hook, description, video_url, thumbnail_url, duration_seconds, has_audio, captions, creator_name, format, sources, published_at, tags, quiz_question_id, verification_status, status, min_age, start_seconds, end_seconds, license, translations) values
  ('v-venus', 'science', 'Auf der Venus ist ein Tag länger als ein Jahr', '243 Erdtage für eine Drehung, nur 225 für einen Umlauf um die Sonne.', 'Die Venus dreht sich extrem langsam – und noch dazu rückwärts. Deshalb dauert eine Drehung um die eigene Achse länger als ein kompletter Umlauf um die Sonne.', '/clips/v-venus.mp4', null, 7.27, true, '["Die Venus dreht sich so langsam,","dass ein Tag dort länger dauert","als ein ganzes Jahr."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Venus (Planet)","url":"https://de.wikipedia.org/wiki/Venus_(Planet)"}]'::jsonb, '2026-10-09T12:00:00Z', array['Planeten', 'Sonnensystem']::text[], 'q-v-venus', 'ai_checked', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-kleopatra', 'history', 'Kleopatra lebte näher an der Mondlandung als am Pyramidenbau', 'Das alte Ägypten dauerte so lange, dass seine Anfänge für Kleopatra schon Altertum waren.', 'Die Cheops-Pyramide entstand um 2560 v. Chr. Kleopatra starb 30 v. Chr. – rund 2500 Jahre später. Bis zur Mondlandung 1969 vergingen danach nur etwa 2000 Jahre.', '/clips/v-kleopatra.mp4', null, 6.91, true, '["Kleopatra lebte näher","an der Mondlandung","als am Bau der großen Pyramide."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Kleopatra VII.","url":"https://de.wikipedia.org/wiki/Kleopatra_VII."},{"name":"Wikipedia: Cheops-Pyramide","url":"https://de.wikipedia.org/wiki/Cheops-Pyramide"}]'::jsonb, '2026-10-08T12:00:00Z', array['Ägypten', 'Zeitgefühl']::text[], 'q-v-kleopatra', 'ai_checked', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-apollo', 'technology', 'Zum Mond mit 4 Kilobyte Arbeitsspeicher', 'Der Apollo-Bordcomputer hatte millionenfach weniger Speicher als ein Smartphone.', 'Der Apollo Guidance Computer hatte 2048 Wörter beschreibbaren Speicher, etwa 4 Kilobyte. Ein Smartphone mit 8 Gigabyte hat rund zwei Millionen Mal so viel.', '/clips/v-apollo.mp4', null, 11.3, true, '["Der Computer, der Menschen zum Mond brachte,","hatte rund vier Kilobyte Arbeitsspeicher.","Ein Smartphone hat millionenfach mehr."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Apollo Guidance Computer","url":"https://de.wikipedia.org/wiki/Apollo_Guidance_Computer"}]'::jsonb, '2026-10-10T12:00:00Z', array['Raumfahrt', 'Computer']::text[], 'q-v-apollo', 'ai_checked', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-luft', 'science', 'Was du gerade einatmest, ist vor allem Stickstoff', 'Luft besteht zu etwa 78 % aus Stickstoff und nur zu 21 % aus Sauerstoff.', 'Trockene Luft enthält rund 78 % Stickstoff, 21 % Sauerstoff und knapp 1 % Argon. Kohlendioxid macht nur einen Bruchteil eines Prozents aus.', '/clips/v-luft.mp4', null, 9.63, true, '["Die Luft, die du atmest,","besteht nur zu einem Fünftel aus Sauerstoff.","Der größte Teil ist Stickstoff."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Erdatmosphäre","url":"https://de.wikipedia.org/wiki/Erdatmosphäre"}]'::jsonb, '2026-10-05T12:00:00Z', array['Atmosphäre', 'Chemie']::text[], 'q-v-luft', 'ai_checked', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-ozean', 'earth', 'Der blaue Planet: mehr Wasser als Land', 'Rund 71 % der Erdoberfläche sind von Wasser bedeckt.', 'Ozeane und Meere bedecken etwa 71 % der Erdoberfläche. Landflächen machen rund 29 % aus – weniger als ein Drittel.', '/clips/v-ozean.mp4', null, 9.26, true, '["Rund 71 Prozent der Erdoberfläche","sind von Wasser bedeckt.","Land macht weniger als ein Drittel aus."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Erde","url":"https://de.wikipedia.org/wiki/Erde"}]'::jsonb, '2026-10-07T12:00:00Z', array['Ozeane', 'Geografie']::text[], 'q-v-ozean', 'ai_checked', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-oxford', 'history', 'Oxford ist älter als das Reich der Azteken', 'In Oxford wurde schon um 1096 gelehrt, Tenochtitlan entstand erst um 1325.', 'Die Lehre in Oxford ist seit etwa 1096 belegt. Tenochtitlan, die Hauptstadt der Azteken, wurde um 1325 gegründet – mehr als zwei Jahrhunderte später.', '/clips/v-oxford.mp4', null, 7.04, true, '["In Oxford wurde schon gelehrt,","als es die Hauptstadt der Azteken","noch gar nicht gab."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: University of Oxford","url":"https://de.wikipedia.org/wiki/University_of_Oxford"},{"name":"Wikipedia: Tenochtitlan","url":"https://de.wikipedia.org/wiki/Tenochtitlan"}]'::jsonb, '2026-10-03T12:00:00Z', array['Mittelalter', 'Zeitgefühl']::text[], 'q-v-oxford', 'ai_checked', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-iss-nacht', 'earth', 'Die Erde bei Nacht – gesehen von der Raumstation', 'Die ISS umrundet die Erde etwa alle 90 Minuten – rund 16 Mal am Tag.', 'Die Internationale Raumstation fliegt in rund 400 Kilometern Höhe mit etwa 28.000 km/h. Der farbige Schimmer über dem Horizont ist das Nachthimmelsleuchten der oberen Atmosphäre.', '/clips/v-iss-nacht.mp4', '/clips/v-iss-nacht.jpg', 10, false, '["So sieht die Erde nachts aus dem All aus.","Die Raumstation fliegt mit rund 28.000 km/h.","Alle 90 Minuten umrundet sie die Erde."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/GSFC_20180124_m12825_ISS_Airglow"}]'::jsonb, '2026-10-12T12:00:00Z', array['ISS', 'Raumfahrt', 'Atmosphäre']::text[], 'q-v-iss-nacht', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"Earth at night – seen from the space station","hook":"The ISS circles the Earth about every 90 minutes – roughly 16 times a day.","description":"The International Space Station flies at an altitude of about 400 kilometres at roughly 28,000 km/h. The coloured shimmer above the horizon is airglow in the upper atmosphere.","captions":["This is what Earth looks like at night from space.","The space station travels at about 28,000 km/h.","It circles the Earth every 90 minutes."]}}'::jsonb),
  ('v-saturn-v', 'history', 'Der Start von Apollo 11', 'Am 16. Juli 1969 hob die Saturn V ab – vier Tage später landeten Menschen auf dem Mond.', 'Die Saturn V war rund 110 Meter hoch und ist bis heute eine der stärksten Raketen, die je geflogen sind. An Bord von Apollo 11: Neil Armstrong, Buzz Aldrin und Michael Collins.', '/clips/v-saturn-v.mp4', '/clips/v-saturn-v.jpg', 4.3, false, '["16. Juli 1969: Apollo 11 startet.","Die Saturn-V-Rakete ist 110 Meter hoch.","Ihr Ziel: der Mond."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/Apollo_11_Intro_720p"}]'::jsonb, '2026-10-11T12:00:00Z', array['Apollo', 'Raumfahrt', 'Mondlandung']::text[], 'q-v-saturn-v', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The launch of Apollo 11","hook":"On 16 July 1969 the Saturn V lifted off – four days later humans landed on the Moon.","description":"The Saturn V was about 110 metres tall and remains one of the most powerful rockets ever flown. On board Apollo 11: Neil Armstrong, Buzz Aldrin and Michael Collins.","captions":["16 July 1969: Apollo 11 lifts off.","The Saturn V rocket is 110 metres tall.","Its destination: the Moon."]}}'::jsonb),
  ('v-aldrin', 'history', 'Der zweite Mensch auf dem Mond', 'Buzz Aldrin stieg rund 19 Minuten nach Neil Armstrong die Leiter der Mondfähre hinab.', 'Originalaufnahme der Fernsehübertragung vom 20. Juli 1969 in restaurierter Fassung. Rund 600 Millionen Menschen verfolgten die Mondlandung live.', '/clips/v-aldrin.mp4', '/clips/v-aldrin.jpg', 10, false, '["20. Juli 1969, Meer der Ruhe.","Buzz Aldrin steigt die Leiter hinab.","Er ist der zweite Mensch auf dem Mond."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/Buzz_Descends_Comparison__720p"}]'::jsonb, '2026-10-10T12:00:00Z', array['Apollo', 'Mondlandung']::text[], 'q-v-aldrin', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The second human on the Moon","hook":"Buzz Aldrin climbed down the lunar module''s ladder about 19 minutes after Neil Armstrong.","description":"Original footage from the television broadcast of 20 July 1969 in a restored version. Around 600 million people watched the Moon landing live.","captions":["20 July 1969, Sea of Tranquility.","Buzz Aldrin climbs down the ladder.","He is the second human on the Moon."]}}'::jsonb),
  ('v-ingenuity', 'technology', 'Ein Hubschrauber auf dem Mars', 'Ingenuity gelang 2021 der erste motorisierte Flug auf einem anderen Planeten.', 'Animation der NASA. Die Marsluft ist rund hundertmal dünner als die der Erde, deshalb drehen sich die Rotoren von Ingenuity mit etwa 2.400 Umdrehungen pro Minute. Geplant waren fünf Flüge – es wurden 72.', '/clips/v-ingenuity.mp4', '/clips/v-ingenuity.jpg', 10, false, '["Das ist Ingenuity, ein Hubschrauber für den Mars.","Die Luft dort ist hundertmal dünner als auf der Erde.","Trotzdem flog er 72 Mal."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/JPL-20200429-TECHf-0002-Mars%20Helicopter%20Animation"}]'::jsonb, '2026-10-09T12:00:00Z', array['Mars', 'Raumfahrt', 'Robotik']::text[], 'q-v-ingenuity', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"A helicopter on Mars","hook":"In 2021 Ingenuity made the first powered flight on another planet.","description":"NASA animation. The Martian air is about a hundred times thinner than Earth''s, so Ingenuity''s rotors spin at around 2,400 revolutions per minute. Five flights were planned – it made 72.","captions":["This is Ingenuity, a helicopter built for Mars.","The air there is a hundred times thinner than on Earth.","It still flew 72 times."]}}'::jsonb),
  ('v-sonne', 'science', 'Unsere Sonne in Bewegung', 'Die Sonne enthält mehr als 99,8 Prozent der gesamten Masse unseres Sonnensystems.', 'Zeitrafferaufnahmen des Sonnenobservatoriums SDO im ultravioletten Licht. Die Sonne ist eine Kugel aus heißem Plasma und besteht vor allem aus Wasserstoff und Helium.', '/clips/v-sonne.mp4', '/clips/v-sonne.jpg', 10, false, '["Das ist unsere Sonne im ultravioletten Licht.","Ihre Oberfläche ist ständig in Bewegung.","Sie enthält 99,8 Prozent der Masse des Sonnensystems."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/GSFC_20160212_SDO_m12144_Year6"}]'::jsonb, '2026-10-08T12:00:00Z', array['Sonne', 'Astronomie']::text[], 'q-v-sonne', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"Our Sun in motion","hook":"The Sun contains more than 99.8 percent of the total mass of our solar system.","description":"Time-lapse footage from the Solar Dynamics Observatory in ultraviolet light. The Sun is a ball of hot plasma made mostly of hydrogen and helium.","captions":["This is our Sun in ultraviolet light.","Its surface is constantly in motion.","It contains 99.8 percent of the solar system''s mass."]}}'::jsonb),
  ('v-hurrikan', 'earth', 'Ein Hurrikan aus dem All', 'Im Auge eines Hurrikans ist es fast windstill – ringsum toben die stärksten Winde.', 'Hurrikan Dorian am 1. September 2019, aufgenommen von Kameras an der Internationalen Raumstation. Tropische Wirbelstürme entstehen über warmem Meerwasser ab etwa 26 Grad.', '/clips/v-hurrikan.mp4', '/clips/v-hurrikan.jpg', 10, false, '["Hurrikan Dorian, gefilmt von der Raumstation.","In der Mitte liegt das fast windstille Auge.","Ringsum toben die stärksten Winde."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/jsc2019m000805_Hurricane_Dorian_190901"}]'::jsonb, '2026-10-07T12:00:00Z', array['Wetter', 'Hurrikan', 'ISS']::text[], 'q-v-hurrikan', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"A hurricane seen from space","hook":"The eye of a hurricane is almost calm – the strongest winds rage all around it.","description":"Hurricane Dorian on 1 September 2019, filmed by cameras on the International Space Station. Tropical cyclones form over warm sea water of about 26 degrees or more.","captions":["Hurricane Dorian, filmed from the space station.","In the middle lies the almost windless eye.","The strongest winds rage all around it."]}}'::jsonb),
  ('v-blitz', 'science', 'Ein Blitz in Zeitlupe', 'Ein Blitz heizt die Luft auf bis zu 30.000 Grad auf – heißer als die Oberfläche der Sonne.', 'Zeitlupenaufnahme mit 240 Bildern pro Sekunde, Finnland. Die schlagartig erhitzte Luft dehnt sich explosionsartig aus: Das hören wir als Donner.', '/clips/v-blitz.mp4', '/clips/v-blitz.jpg', 6, false, '["Ein Blitz, zehnfach verlangsamt.","Er erhitzt die Luft auf bis zu 30.000 Grad.","Die Druckwelle hören wir als Donner."]'::jsonb, 'MrNousia', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Lightning_strikes_in_slow_motion_(240fps)_in_Muurame,_Finland.webm"}]'::jsonb, '2026-10-06T12:00:00Z', array['Wetter', 'Physik']::text[], 'q-v-blitz', 'ai_checked', 'published', 10, null, null, 'CC BY 3.0, MrNousia – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"Lightning in slow motion","hook":"A lightning bolt heats the air to as much as 30,000 degrees – hotter than the surface of the Sun.","description":"Slow-motion footage at 240 frames per second, Finland. The suddenly heated air expands explosively: we hear that as thunder.","captions":["A lightning bolt, slowed down tenfold.","It heats the air to as much as 30,000 degrees.","We hear the shock wave as thunder."]}}'::jsonb),
  ('v-polarlicht', 'science', 'Polarlichter über Alaska', 'Polarlichter entstehen, wenn geladene Teilchen von der Sonne auf die obere Atmosphäre treffen.', 'Zeitraffer aus Alaska. Das grüne Leuchten stammt von Sauerstoffatomen in rund 100 Kilometern Höhe, die durch die Teilchen des Sonnenwinds angeregt werden.', '/clips/v-polarlicht.mp4', '/clips/v-polarlicht.jpg', 8.5, false, '["Polarlichter über Alaska im Zeitraffer.","Teilchen von der Sonne treffen auf die Atmosphäre.","Grün leuchtet der Sauerstoff."]'::jsonb, 'NASA Scientific Visualization Studio', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Alaskan_Aurora_Time_Lapse_(SVS15077).webm"}]'::jsonb, '2026-10-05T12:00:00Z', array['Sonne', 'Atmosphäre']::text[], 'q-v-polarlicht', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"Northern lights over Alaska","hook":"Auroras occur when charged particles from the Sun hit the upper atmosphere.","description":"Time-lapse from Alaska. The green glow comes from oxygen atoms about 100 kilometres up that are excited by solar wind particles.","captions":["Northern lights over Alaska in time-lapse.","Particles from the Sun hit the atmosphere.","The green glow is oxygen."]}}'::jsonb),
  ('v-keimung', 'science', 'Aus Samen werden Pflanzen', 'Ein Samen enthält einen winzigen Keimling und Nahrung für den Start – Wasser weckt ihn auf.', 'Linsen keimen im Zeitraffer. Zum Keimen braucht ein Samen Wasser, Wärme und Sauerstoff. Licht wird erst wichtig, wenn die ersten Blätter erscheinen.', '/clips/v-keimung.mp4', '/clips/v-keimung.jpg', 11, false, '["Linsen keimen im Zeitraffer.","Im Samen steckt Nahrung für den Start.","Wasser weckt den Keimling auf."]'::jsonb, 'Always Shooting', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Lentil_microgreens_growth_time_lapse.webm"}]'::jsonb, '2026-10-04T12:00:00Z', array['Pflanzen', 'Biologie']::text[], 'q-v-keimung', 'ai_checked', 'published', 6, null, null, 'CC BY 2.0, Always Shooting – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"From seed to plant","hook":"A seed contains a tiny embryo and food for the start – water wakes it up.","description":"Lentils sprouting in time-lapse. To germinate, a seed needs water, warmth and oxygen. Light only becomes important once the first leaves appear.","captions":["Lentils sprouting in time-lapse.","The seed holds food for the start.","Water wakes the embryo up."]}}'::jsonb),
  ('v-tacoma', 'technology', 'Die Brücke, die sich selbst zerriss', '1940 versetzte Wind die Tacoma-Narrows-Brücke in immer stärkere Schwingungen – bis sie einstürzte.', 'Die Hängebrücke im US-Bundesstaat Washington war erst vier Monate alt. Seit dem Einsturz werden große Brücken im Windkanal getestet. Verletzt wurde niemand.', '/clips/v-tacoma.mp4', '/clips/v-tacoma.jpg', 8, false, '["Tacoma, USA, 7. November 1940.","Der Wind lässt die Fahrbahn schwingen.","Wenig später stürzt die Brücke ein."]'::jsonb, 'Barney Elliot', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Tacoma_Narrows_Bridge_destruction.ogv"}]'::jsonb, '2026-10-03T12:00:00Z', array['Ingenieurwesen', 'Physik']::text[], 'q-v-tacoma', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The bridge that tore itself apart","hook":"In 1940 wind set the Tacoma Narrows Bridge swinging more and more violently – until it collapsed.","description":"The suspension bridge in the US state of Washington was only four months old. Since the collapse, large bridges have been tested in wind tunnels. Nobody was hurt.","captions":["Tacoma, USA, 7 November 1940.","The wind makes the roadway oscillate.","A little later the bridge collapses."]}}'::jsonb),
  ('v-3d-druck', 'technology', 'So arbeitet ein 3D-Drucker', 'Ein 3D-Drucker baut Gegenstände Schicht für Schicht aus geschmolzenem Kunststoff auf.', 'Zeitraffer eines Druckvorgangs. Die Düse fährt jede Schicht nach einem digitalen Bauplan ab; was hier Sekunden dauert, braucht in Wirklichkeit oft Stunden.', '/clips/v-3d-druck.mp4', '/clips/v-3d-druck.jpg', 6, false, '["Ein 3D-Drucker im Zeitraffer.","Schicht für Schicht wächst die Figur.","Der Bauplan kommt aus dem Computer."]'::jsonb, 'RepRapPro', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Robot_3D_print_timelapse_on_RepRapPro_Fisher.webm"}]'::jsonb, '2026-10-02T12:00:00Z', array['Fertigung', 'Maker']::text[], 'q-v-3d-druck', 'ai_checked', 'published', 10, null, null, 'CC BY 3.0, RepRapPro – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"How a 3D printer works","hook":"A 3D printer builds objects layer by layer from molten plastic.","description":"Time-lapse of a print. The nozzle traces each layer from a digital blueprint; what takes seconds here often takes hours in reality.","captions":["A 3D printer in time-lapse.","The figure grows layer by layer.","The blueprint comes from a computer."]}}'::jsonb),
  ('v-mars-landung', 'technology', 'Landung auf dem Mars – mit Bordkamera', 'So sah der Rover Perseverance 2021 seine eigene Landung auf dem Mars.', 'Blick der Bordkamera nach unten auf den Krater Jezero, 18. Februar 2021. Auf den letzten Metern ließ eine schwebende Plattform den Rover an Seilen herab.', '/clips/v-mars-landung.mp4', '/clips/v-mars-landung.jpg', 10, false, '["18. Februar 2021: Anflug auf den Mars.","Die Bordkamera blickt auf den Krater Jezero.","Sekunden später setzt der Rover auf."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/JPL-20210222-M2020f-0001-Perseverance%20Rover%E2%80%99s%20Descent%20and%20Touchdown%20on%20Mars"}]'::jsonb, '2026-10-01T12:00:00Z', array['Mars', 'Raumfahrt']::text[], 'q-v-mars-landung', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"Landing on Mars – onboard camera","hook":"This is how the rover Perseverance saw its own landing on Mars in 2021.","description":"The onboard camera looks down at Jezero Crater, 18 February 2021. For the final metres, a hovering platform lowered the rover on cables.","captions":["18 February 2021: approaching Mars.","The onboard camera looks at Jezero Crater.","Seconds later the rover touches down."]}}'::jsonb),
  ('v-erdaufgang', 'history', 'Der erste Erdaufgang', 'An Heiligabend 1968 sahen Menschen zum ersten Mal die Erde über dem Mond aufgehen.', 'Die Besatzung von Apollo 8 umkreiste als erste den Mond. Die Visualisierung der NASA rekonstruiert den Moment, in dem William Anders das berühmte Foto „Earthrise“ aufnahm.', '/clips/v-erdaufgang.mp4', '/clips/v-erdaufgang.jpg', 10, false, '["24. Dezember 1968, Mondumlaufbahn.","Über dem Horizont geht die Erde auf.","Drei Menschen sehen das als Erste."]'::jsonb, 'NASA / Goddard Space Flight Center', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Earthrise.ogv"}]'::jsonb, '2026-09-30T12:00:00Z', array['Apollo', 'Raumfahrt']::text[], 'q-v-erdaufgang', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The first Earthrise","hook":"On Christmas Eve 1968, humans saw the Earth rise over the Moon for the first time.","description":"The crew of Apollo 8 were the first to orbit the Moon. NASA''s visualisation reconstructs the moment William Anders took the famous “Earthrise” photograph.","captions":["24 December 1968, lunar orbit.","The Earth rises above the horizon.","Three people are the first to see it."]}}'::jsonb),
  ('v-titanic', 'history', 'Die Titanic vor ihrer ersten Fahrt', 'Die Titanic war 269 Meter lang und galt 1912 als größtes Schiff der Welt.', 'Zeitgenössische Filmaufnahmen aus dem Archiv von British Pathé (1911–1912). Auf ihrer Jungfernfahrt stieß die Titanic mit einem Eisberg zusammen und sank am 15. April 1912; rund 1.500 Menschen starben.', '/clips/v-titanic.mp4', '/clips/v-titanic.jpg', 8, false, '["Aufnahmen aus den Jahren 1911 und 1912.","Die Titanic ist 269 Meter lang.","Ihre erste Fahrt ist auch ihre letzte."]'::jsonb, 'British Pathé', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Titanic_Disaster_-_Genuine_Footage_(1911-1912)(enhanced).webm"}]'::jsonb, '2026-09-29T12:00:00Z', array['Schifffahrt', '20. Jahrhundert']::text[], 'q-v-titanic', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The Titanic before her maiden voyage","hook":"The Titanic was 269 metres long and in 1912 was considered the largest ship in the world.","description":"Contemporary film footage from the British Pathé archive (1911–1912). On her maiden voyage the Titanic struck an iceberg and sank on 15 April 1912; about 1,500 people died.","captions":["Footage from 1911 and 1912.","The Titanic is 269 metres long.","Her first voyage is also her last."]}}'::jsonb),
  ('v-flugpioniere', 'history', 'Als das Fliegen begann', '1903 gelang den Brüdern Wright der erste gesteuerte Motorflug – er dauerte zwölf Sekunden.', 'Filmaufnahmen früher Flugzeuge aus den ersten Jahren der Luftfahrt. Nur 66 Jahre nach dem ersten Motorflug landeten Menschen auf dem Mond.', '/clips/v-flugpioniere.mp4', '/clips/v-flugpioniere.jpg', 4, false, '["Flugzeuge aus den Anfangsjahren der Luftfahrt.","1903 flogen die Brüder Wright zwölf Sekunden.","66 Jahre später: die Mondlandung."]'::jsonb, 'Unbekannt (gemeinfrei)', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:First_flights_in_aviation_history.ogv"}]'::jsonb, '2026-09-28T12:00:00Z', array['Luftfahrt']::text[], 'q-v-flugpioniere', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"When flying began","hook":"In 1903 the Wright brothers made the first controlled powered flight – it lasted twelve seconds.","description":"Film footage of early aircraft from the first years of aviation. Only 66 years after the first powered flight, humans landed on the Moon.","captions":["Aircraft from the early years of aviation.","In 1903 the Wright brothers flew for twelve seconds.","66 years later: the Moon landing."]}}'::jsonb),
  ('v-buchdruck', 'history', 'Drucken wie zu Gutenbergs Zeit', 'Hochdruck: Farbe kommt auf erhabene Lettern, dann wird Papier dagegengepresst.', 'Eine Tiegeldruckpresse in Indien. Das Prinzip geht auf Johannes Gutenberg zurück, der um 1450 in Mainz den Druck mit beweglichen Metalllettern entwickelte.', '/clips/v-buchdruck.mp4', '/clips/v-buchdruck.jpg', 10, false, '["Eine Druckpresse mit beweglichen Lettern.","Walzen tragen die Farbe auf.","Das Prinzip stammt von Gutenberg, um 1450."]'::jsonb, 'Subhashish Panigrahi', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Printing_in_a_letterpress.webm"}]'::jsonb, '2026-09-27T12:00:00Z', array['Buchdruck', 'Medien']::text[], 'q-v-buchdruck', 'ai_checked', 'published', 10, null, null, 'CC BY-SA 4.0, Subhashish Panigrahi – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"Printing as in Gutenberg''s day","hook":"Letterpress: ink is applied to raised type, then paper is pressed against it.","description":"A platen press in India. The principle goes back to Johannes Gutenberg, who developed printing with movable metal type in Mainz around 1450.","captions":["A printing press with movable type.","Rollers apply the ink.","The principle is Gutenberg''s, from around 1450."]}}'::jsonb),
  ('v-lumiere', 'culture', 'Einer der ersten Filme der Welt', '1895 zeigten die Brüder Lumière in Paris erstmals Filme vor zahlendem Publikum – die Geburt des Kinos.', '„Die Ankunft eines Zuges auf dem Bahnhof in La Ciotat“, gedreht Mitte der 1890er-Jahre. Dass die Zuschauer vor dem Zug aus dem Saal flohen, ist eine beliebte, aber unbelegte Legende.', '/clips/v-lumiere.mp4', '/clips/v-lumiere.jpg', 8, false, '["Frankreich, Mitte der 1890er-Jahre.","Ein Zug fährt in den Bahnhof ein.","So begann das Kino."]'::jsonb, 'Auguste und Louis Lumière', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:L%27Arriv%C3%A9e_d%27un_train_en_gare_de_La_Ciotat_(1897).webm"}]'::jsonb, '2026-09-26T12:00:00Z', array['Film', 'Kino']::text[], 'q-v-lumiere', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"One of the world''s first films","hook":"In 1895 the Lumière brothers showed films to a paying audience in Paris for the first time – the birth of cinema.","description":"“The Arrival of a Train at La Ciotat Station”, shot in the mid-1890s. That audiences fled the room from the train is a popular but unproven legend.","captions":["France, mid-1890s.","A train pulls into the station.","This is how cinema began."]}}'::jsonb),
  ('v-roundhay', 'culture', 'Der älteste erhaltene Film', 'Diese zwei Sekunden aus einem Garten in Leeds sind der älteste erhaltene Film der Welt – gedreht 1888.', '„Roundhay Garden Scene“ von Louis Le Prince, aufgenommen am 14. Oktober 1888 in England. Der Clip zeigt die Szene mehrmals hintereinander.', '/clips/v-roundhay.mp4', '/clips/v-roundhay.jpg', 8, false, '["Leeds, England, 14. Oktober 1888.","Vier Menschen gehen durch einen Garten.","Es ist der älteste erhaltene Film."]'::jsonb, 'Louis Le Prince', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Roundhay_Garden_Scene_(1888).webm"}]'::jsonb, '2026-09-25T12:00:00Z', array['Film', 'Erfindungen']::text[], 'q-v-roundhay', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The oldest surviving film","hook":"These two seconds from a garden in Leeds are the oldest surviving film in the world – shot in 1888.","description":"“Roundhay Garden Scene” by Louis Le Prince, filmed in England on 14 October 1888. The clip shows the scene several times in a row.","captions":["Leeds, England, 14 October 1888.","Four people walk through a garden.","It is the oldest surviving film."]}}'::jsonb),
  ('v-reise-zum-mond', 'culture', 'Der erste Science-Fiction-Film', '„Die Reise zum Mond“ von 1902 gilt als erster Science-Fiction-Film der Geschichte.', 'Der französische Zauberkünstler Georges Méliès erfand für seine Filme Tricks wie Stopptrick und Mehrfachbelichtung. Jede Kulisse war von Hand gemalt.', '/clips/v-reise-zum-mond.mp4', '/clips/v-reise-zum-mond.jpg', 8, false, '["Frankreich, 1902.","Georges Méliès schickt Forscher zum Mond.","Alle Tricks entstehen direkt in der Kamera."]'::jsonb, 'Georges Méliès', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Le_Voyage_dans_la_Lune_(1902).webm"}]'::jsonb, '2026-09-24T12:00:00Z', array['Film', 'Science-Fiction']::text[], 'q-v-reise-zum-mond', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The first science-fiction film","hook":"“A Trip to the Moon” from 1902 is regarded as the first science-fiction film in history.","description":"The French stage magician Georges Méliès invented tricks such as the stop trick and multiple exposure for his films. Every set was painted by hand.","captions":["France, 1902.","Georges Méliès sends explorers to the Moon.","All the tricks are created in the camera."]}}'::jsonb),
  ('v-orchester', 'culture', 'Wie ein Orchester aufgebaut ist', 'Ein Sinfonieorchester hat vier Gruppen: Streicher, Holzbläser, Blechbläser und Schlagwerk.', 'Das Sinfonieorchester der University of Colorado Boulder spielt Beethovens 5. Sinfonie. Vorn sitzen die Streicher, dahinter die Bläser, ganz hinten das Schlagwerk.', '/clips/v-orchester.mp4', '/clips/v-orchester.jpg', 8, false, '["Ein Sinfonieorchester bei der Arbeit.","Vorn die Streicher, dahinter die Bläser.","Der Dirigent hält alle zusammen."]'::jsonb, 'University of Colorado Boulder College of Music', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Beethoven_Symphony_No._5,_Mvmt_1_-_University_of_Colorado_Boulder_Symphony_Orchestra.webm"}]'::jsonb, '2026-09-23T12:00:00Z', array['Musik', 'Klassik']::text[], 'q-v-orchester', 'ai_checked', 'published', 10, null, null, 'CC BY 3.0, University of Colorado Boulder College of Music – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"How an orchestra is organised","hook":"A symphony orchestra has four sections: strings, woodwind, brass and percussion.","description":"The University of Colorado Boulder Symphony Orchestra plays Beethoven''s Fifth Symphony. The strings sit at the front, the wind players behind them, percussion at the very back.","captions":["A symphony orchestra at work.","Strings at the front, wind players behind.","The conductor holds everyone together."]}}'::jsonb),
  ('v-vulkan', 'earth', 'Blick in einen Vulkankrater', 'Lava ist rund 1.000 Grad heiß. Solange das geschmolzene Gestein unter der Erde ist, heißt es Magma.', 'Ausbruch am Litli-Hrútur in Island, 2023. Island liegt auf der Grenze zweier Erdplatten, die auseinanderdriften – deshalb gibt es dort so viele Vulkane.', '/clips/v-vulkan.mp4', '/clips/v-vulkan.jpg', 8, false, '["Island, 2023: ein Vulkan bricht aus.","Die Lava ist rund 1.000 Grad heiß.","Unter der Erde heißt sie Magma."]'::jsonb, 'Giles Laurent', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:007_Volcano_eruption_of_Litli-Hr%C3%BAtur_in_Iceland_in_2023_Video_by_Giles_Laurent.webm"}]'::jsonb, '2026-09-22T12:00:00Z', array['Vulkane', 'Geologie']::text[], 'q-v-vulkan', 'ai_checked', 'published', 10, null, null, 'CC BY-SA 4.0, Giles Laurent – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"Looking into a volcanic crater","hook":"Lava is about 1,000 degrees hot. As long as the molten rock is underground, it is called magma.","description":"Eruption at Litli-Hrútur in Iceland, 2023. Iceland lies on the boundary of two tectonic plates that are drifting apart – which is why it has so many volcanoes.","captions":["Iceland, 2023: a volcano erupts.","The lava is about 1,000 degrees hot.","Underground it is called magma."]}}'::jsonb),
  ('v-gepard', 'earth', 'Das schnellste Landtier', 'Ein Gepard beschleunigt in etwa drei Sekunden auf fast 100 km/h.', 'Zeitlupenaufnahme eines sprintenden Gepards. Die biegsame Wirbelsäule wirkt wie eine Feder, der lange Schwanz hält das Tier in der Kurve im Gleichgewicht.', '/clips/v-gepard.mp4', '/clips/v-gepard.jpg', 8, false, '["Ein Gepard im Sprint, stark verlangsamt.","In drei Sekunden auf fast 100 km/h.","Der Schwanz hilft beim Steuern."]'::jsonb, 'Gregory Wilson', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Cheetahs_on_the_Edge_(Director%27s_Cut).webm"}]'::jsonb, '2026-10-12T12:00:00Z', array['Tiere', 'Rekorde']::text[], 'q-v-gepard', 'ai_checked', 'published', 6, null, null, 'CC BY 3.0, Gregory Wilson – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"The fastest land animal","hook":"A cheetah accelerates to almost 100 km/h in about three seconds.","description":"Slow-motion footage of a sprinting cheetah. The flexible spine works like a spring, and the long tail keeps the animal balanced in turns.","captions":["A cheetah sprinting, greatly slowed down.","To almost 100 km/h in three seconds.","The tail helps with steering."]}}'::jsonb),
  ('v-oktopus', 'earth', 'Drei Herzen, blaues Blut', 'Ein Oktopus hat drei Herzen, blaues Blut und acht Arme, die teilweise selbstständig handeln.', 'Zwei Drittel der Nervenzellen eines Oktopus sitzen in den Armen. Sein Blut ist blau, weil es Sauerstoff mit Kupfer statt mit Eisen transportiert.', '/clips/v-oktopus.mp4', '/clips/v-oktopus.jpg', 9, false, '["Ein Oktopus im Aquarium.","Er hat drei Herzen und blaues Blut.","Seine Arme denken ein Stück weit mit."]'::jsonb, 'MartinThoma', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Sealife-Munich-Octopus-2.ogv"}]'::jsonb, '2026-10-11T12:00:00Z', array['Tiere', 'Meer']::text[], 'q-v-oktopus', 'ai_checked', 'published', 6, null, null, 'CC0 (gemeinfrei)', '{"en":{"title":"Three hearts, blue blood","hook":"An octopus has three hearts, blue blood and eight arms that act partly on their own.","description":"Two thirds of an octopus''s nerve cells are in its arms. Its blood is blue because it carries oxygen with copper instead of iron.","captions":["An octopus in an aquarium.","It has three hearts and blue blood.","Its arms do some of the thinking."]}}'::jsonb),
  ('v-bienen', 'earth', 'Bienen sprechen im Tanz', 'Mit dem Schwänzeltanz zeigen Honigbienen ihren Schwestern, in welcher Richtung und wie weit entfernt Futter liegt.', 'Honigbienen auf der Wabe. Die Richtung des Tanzes zeigt den Winkel zur Sonne, die Dauer des Schwänzelns die Entfernung. Für diese Entdeckung erhielt Karl von Frisch 1973 den Nobelpreis.', '/clips/v-bienen.mp4', '/clips/v-bienen.jpg', 8, false, '["Honigbienen auf ihrer Wabe.","Mit einem Tanz zeigen sie den Weg zum Futter.","Richtung und Dauer verraten, wo es liegt."]'::jsonb, 'OakleyOriginals', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Waggle_Dance.webm"}]'::jsonb, '2026-10-10T12:00:00Z', array['Tiere', 'Insekten']::text[], 'q-v-bienen', 'ai_checked', 'published', 10, null, null, 'CC BY 2.0, OakleyOriginals – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"Bees talk by dancing","hook":"With the waggle dance, honeybees show their sisters in which direction and how far away food is.","description":"Honeybees on the comb. The direction of the dance gives the angle to the Sun, the length of the waggle the distance. Karl von Frisch received the Nobel Prize in 1973 for this discovery.","captions":["Honeybees on their comb.","A dance shows the way to food.","Direction and duration reveal where it is."]}}'::jsonb),
  ('v-stare', 'earth', 'Tausend Vögel, eine Bewegung', 'In einem Starenschwarm achtet jeder Vogel nur auf seine nächsten Nachbarn – daraus entsteht die gemeinsame Bewegung.', 'Stare sammeln sich abends zu riesigen Schwärmen. Niemand führt den Schwarm an. Die dichten, wogenden Formen machen es Greifvögeln schwer, ein einzelnes Tier zu fassen.', '/clips/v-stare.mp4', '/clips/v-stare.jpg', 9, false, '["Stare sammeln sich in der Abenddämmerung.","Niemand führt den Schwarm an.","Jeder Vogel achtet nur auf seine Nachbarn."]'::jsonb, 'Karen Roe', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Flock_of_starlings_(Sturnus_vulgaris).webm"}]'::jsonb, '2026-10-09T12:00:00Z', array['Tiere', 'Vögel']::text[], 'q-v-stare', 'ai_checked', 'published', 10, null, null, 'CC BY 2.0, Karen Roe – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"A thousand birds, one movement","hook":"In a flock of starlings each bird watches only its nearest neighbours – that is what creates the shared movement.","description":"Starlings gather in huge flocks in the evening. Nobody leads the flock. The dense, swirling shapes make it hard for birds of prey to pick out a single animal.","captions":["Starlings gather at dusk.","Nobody leads the flock.","Each bird watches only its neighbours."]}}'::jsonb),
  ('v-banknoten', 'economy', 'So entsteht ein 20-Euro-Schein', 'Euro-Banknoten bestehen nicht aus Papier, sondern aus reiner Baumwollfaser.', 'Druck der 20-Euro-Note. Baumwolle macht die Scheine reißfest und gibt ihnen ihren typischen Griff. Wasserzeichen, Hologramm und Sicherheitsfaden erschweren Fälschungen.', '/clips/v-banknoten.mp4', '/clips/v-banknoten.jpg', 8, false, '["Hier werden 20-Euro-Scheine gedruckt.","Sie bestehen aus Baumwolle, nicht aus Papier.","Viele Merkmale schützen vor Fälschung."]'::jsonb, 'Europäische Zentralbank', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:New_20_Euro_Banknotes_Printing_Production.webm"}]'::jsonb, '2026-10-08T12:00:00Z', array['Geld', 'Euro']::text[], 'q-v-banknoten', 'ai_checked', 'published', 10, null, null, 'CC BY 3.0, Europäische Zentralbank – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"How a 20-euro note is made","hook":"Euro banknotes are not made of paper but of pure cotton fibre.","description":"Printing the 20-euro note. Cotton makes the notes tear-resistant and gives them their typical feel. Watermark, hologram and security thread make counterfeiting harder.","captions":["This is where 20-euro notes are printed.","They are made of cotton, not paper.","Many features protect against forgery."]}}'::jsonb),
  ('v-muenzen', 'economy', 'Wie Münzen entstehen', 'Münzen werden geprägt: Stempel pressen das Motiv mit vielen Tonnen Druck in einen Metallrohling.', 'Frisch geprägte Quarter-Dollar-Münzen in der US-Münzanstalt West Point. Moderne Prägemaschinen schaffen mehrere Hundert Münzen pro Minute.', '/clips/v-muenzen.mp4', '/clips/v-muenzen.jpg', 6, false, '["Frisch geprägte Münzen in den USA.","Ein Stempel presst das Motiv ins Metall.","Hunderte Münzen pro Minute."]'::jsonb, 'United States Mint', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:West_Point_Quarters_B-Roll.webm"}]'::jsonb, '2026-10-07T12:00:00Z', array['Geld', 'Münzen']::text[], 'q-v-muenzen', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"How coins are made","hook":"Coins are minted: dies press the design into a metal blank with many tonnes of pressure.","description":"Freshly minted quarter-dollar coins at the US Mint in West Point. Modern coining presses produce several hundred coins a minute.","captions":["Freshly minted coins in the USA.","A die presses the design into the metal.","Hundreds of coins a minute."]}}'::jsonb),
  ('v-container', 'economy', 'Die Kiste, die den Welthandel veränderte', 'Rund 80 Prozent des Welthandels reisen per Schiff – der größte Teil der Stückgüter in genormten Containern.', 'Zeitraffer in einem Containerterminal in Gdynia, Polen. Weil Container weltweit dieselben Maße haben, passen sie auf Schiffe, Züge und Lastwagen – das Umladen dauert Minuten statt Tage.', '/clips/v-container.mp4', '/clips/v-container.jpg', 10, false, '["Ein Containerhafen im Zeitraffer.","Alle Container haben weltweit dieselben Maße.","So wurde Transport schnell und billig."]'::jsonb, 'PaSt Photo', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:MSC_Paris_-_berthing_at_BCT_Gdynia,_Timelapse..webm"}]'::jsonb, '2026-10-06T12:00:00Z', array['Handel', 'Logistik']::text[], 'q-v-container', 'ai_checked', 'published', 10, null, null, 'CC BY 3.0, PaSt Photo – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"The box that changed world trade","hook":"About 80 percent of world trade travels by ship – most general cargo in standardised containers.","description":"Time-lapse at a container terminal in Gdynia, Poland. Because containers have the same dimensions worldwide, they fit on ships, trains and lorries – transferring them takes minutes instead of days.","captions":["A container port in time-lapse.","All containers have the same dimensions worldwide.","That made transport fast and cheap."]}}'::jsonb),
  ('v-fliessband', 'business', 'Die Idee, die Autos bezahlbar machte', 'Henry Fords Fließband senkte die Bauzeit eines Autos von über zwölf Stunden auf rund anderthalb.', 'Aufnahmen aus einem Ford-Werk, um 1924. Jeder Arbeiter führte nur wenige Handgriffe aus, das Werkstück kam zu ihm. So sank der Preis des Model T von 850 auf unter 300 Dollar.', '/clips/v-fliessband.mp4', '/clips/v-fliessband.jpg', 8, false, '["Ein Ford-Werk in den 1920er-Jahren.","Jeder macht nur wenige Handgriffe.","So wurden Autos für viele bezahlbar."]'::jsonb, 'Ford Motor Company', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Model_T_assembling_circa_1924.webm"}]'::jsonb, '2026-10-05T12:00:00Z', array['Industrie', 'Unternehmen']::text[], 'q-v-fliessband', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The idea that made cars affordable","hook":"Henry Ford''s assembly line cut the time to build a car from more than twelve hours to about an hour and a half.","description":"Footage from a Ford plant, around 1924. Each worker performed only a few movements; the workpiece came to him. The price of the Model T fell from 850 to under 300 dollars.","captions":["A Ford plant in the 1920s.","Each worker does only a few movements.","That made cars affordable for many."]}}'::jsonb),
  ('v-supermarkt', 'business', 'Die Erfindung der Selbstbedienung', '1916 eröffnete in den USA der erste Laden, in dem Kunden die Ware selbst aus dem Regal nahmen.', 'Werbefilm eines kalifornischen Einkaufszentrums von 1957. Selbstbedienung senkte die Personalkosten und machte Verpackung und Marken wichtiger: Das Produkt musste sich nun selbst verkaufen.', '/clips/v-supermarkt.mp4', '/clips/v-supermarkt.jpg', 8, false, '["Ein Supermarkt in Kalifornien, 1957.","Kunden bedienen sich selbst.","Die Idee stammt aus dem Jahr 1916."]'::jsonb, 'Hillsdale Shopping Center', 'footage', '[{"name":"Internet Archive (Prelinger Archives)","url":"https://archive.org/details/Shopping1957"}]'::jsonb, '2026-10-04T12:00:00Z', array['Handel', 'Geschäftsmodell']::text[], 'q-v-supermarkt', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The invention of self-service","hook":"In 1916 the first shop opened in the USA where customers took goods from the shelves themselves.","description":"Promotional film for a Californian shopping centre from 1957. Self-service lowered staff costs and made packaging and brands more important: the product now had to sell itself.","captions":["A supermarket in California, 1957.","Customers serve themselves.","The idea dates from 1916."]}}'::jsonb),
  ('v-buero', 'business', 'Büroarbeit vor dem Computer', '1950 wurde jeder Brief und jede Rechnung auf der Schreibmaschine getippt – unsere Tastatur stammt aus dieser Welt.', 'Lehrfilm „Office Etiquette“ von 1950. Die Tastenanordnung QWERTY wurde in den 1870er-Jahren für Schreibmaschinen entwickelt und ist bis heute Standard, im Deutschen als QWERTZ.', '/clips/v-buero.mp4', '/clips/v-buero.jpg', 5, false, '["Ein Büro im Jahr 1950.","Jeder Brief entsteht auf der Schreibmaschine.","Ihre Tastatur nutzen wir noch heute."]'::jsonb, 'Coronet Instructional Films', 'footage', '[{"name":"Internet Archive (Prelinger Archives)","url":"https://archive.org/details/OfficeEt1950"}]'::jsonb, '2026-10-03T12:00:00Z', array['Arbeit', 'Büro']::text[], 'q-v-buero', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"Office work before the computer","hook":"In 1950 every letter and invoice was typed on a typewriter – our keyboard comes from that world.","description":"Educational film “Office Etiquette” from 1950. The QWERTY layout was developed for typewriters in the 1870s and is still the standard today.","captions":["An office in 1950.","Every letter is written on a typewriter.","We still use its keyboard today."]}}'::jsonb)
